insert into public.item_content (item_id,lesson,questions) select id,$q$<h3>Səs və hərf</h3>
<p>Danışarkən tələffüz etdiyimiz şey səs, yazıda onu göstərən işarə isə hərfdir. Azərbaycan əlifbası
32 hərfdən ibarətdir: 9 sait, 23 samit.</p>

<h3>Saitlər</h3>
<p>Saitlər ağız boşluğundan sərbəst çıxan səslərdir: <b>a, e, ə, i, ı, o, ö, u, ü</b>. Üç cür bölünür:</p>
<div class="tscroll"><table>
<tr><th>Bölgü</th><th>Qrup</th><th>Saitlər</th></tr>
<tr><td rowspan="2">Dilin arxa və ön hissəsinə görə</td><td>Qalın</td><td>a, ı, o, u</td></tr>
<tr><td>İncə</td><td>e, ə, i, ö, ü</td></tr>
<tr><td rowspan="2">Dodaqların vəziyyətinə görə</td><td>Dodaqlanan</td><td>o, ö, u, ü</td></tr>
<tr><td>Dodaqlanmayan</td><td>a, e, ə, i, ı</td></tr>
<tr><td rowspan="2">Ağzın açılma dərəcəsinə görə</td><td>Qapalı</td><td>ı, i, u, ü</td></tr>
<tr><td>Açıq</td><td>a, e, ə, o, ö</td></tr>
</table></div>

<h3>Samitlər</h3>
<p>Samitlər kar və cingiltili olmaqla iki yerə bölünür. Çoxu cütlük təşkil edir:
b–p, v–f, g–k, ğ–x, d–t, j–ş, z–s, c–ç.</p>
<ul>
<li><b>Kar qarşılığı olmayan</b> (sonor) samitlər: y, l, m, n, r</li>
<li><b>Cingiltili qarşılığı olmayan</b> samit: h</li>
</ul>

<h3>Heca və vurğu</h3>
<p>Hecaların sayı sözdəki saitlərin sayına bərabərdir: <i>mü-əl-lim</i> — 3 sait, 3 heca.
Azərbaycan dilində vurğu əsasən son hecaya düşür. Zərflərdə isə çox vaxt birinci hecaya düşür:
<i>dü</i>nən, <i>in</i>di.</p>
<div class="ex">Vurğu bəzən mənanı dəyişir: alm<b>á</b> (meyvə) — <b>á</b>lma (almamaq əmri).</div>

<h3>Ahəng qanunu</h3>
<p>Sözdə saitlərin ya hamısının qalın, ya da hamısının incə olmasına ahəng qanunu deyilir:
<i>qapılar</i> (hamısı qalın), <i>gözlük</i> (hamısı incə). Alınma sözlərin bir çoxu bu qanuna tabe deyil:
<i>kitab, ilan, işıq</i>.</p>

<h3>Başlıca fonetik hadisələr</h3>
<ul>
<li><b>Saitin düşməsi:</b> ağız → ağzı, burun → burnu, sinif → sinfi</li>
<li><b>Samitin artması</b> (bitişdirici y, n, s): ata → atası, ata → ataya</li>
<li><b>Səs əvəzlənməsi:</b> çörək → çörəyi (k → y)</li>
<li><b>Karlaşma:</b> «kitab» sözü [kitap], «palıd» sözü [palıt] kimi tələffüz olunur</li>
</ul>$q$,$q$[{"s": "Azərbaycan əlifbasında neçə hərf var?", "o": ["29", "31", "32", "33"], "a": 2, "e": "Azərbaycan əlifbası 32 hərfdən ibarətdir: 9 sait, 23 samit."}, {"s": "Azərbaycan dilində neçə sait səs var?", "o": ["6", "8", "9", "10"], "a": 2, "e": "Saitlər: a, e, ə, i, ı, o, ö, u, ü — cəmi 9."}, {"s": "Hansı cərgədəki saitlərin hamısı qalındır?", "o": ["a, ı, o, u", "ə, i, ö, ü", "a, e, o, u", "ı, i, u, ü"], "a": 0, "e": "Qalın saitlər: a, ı, o, u. Qalan beşi (e, ə, i, ö, ü) incədir."}, {"s": "Hansı cərgədəki saitlərin hamısı incədir?", "o": ["a, ı, o, u", "e, ə, i, ö, ü", "a, e, i, o", "ı, o, u, ü"], "a": 1, "e": "İncə saitlər: e, ə, i, ö, ü."}, {"s": "Hansı cərgədəki saitlərin hamısı dodaqlanandır?", "o": ["a, ı, e, ə", "o, u, ö, ü", "i, ü, e, o", "a, o, u, ı"], "a": 1, "e": "Dodaqlanan saitlər: o, u, ö, ü. Qalanları dodaqlanmayandır."}, {"s": "Azərbaycan dilində neçə samit var?", "o": ["21", "23", "25", "26"], "a": 1, "e": "32 hərfdən 9-u sait, 23-ü samitdir."}, {"s": "Kar qarşılığı olmayan (sonor) samitlər hansı cərgədədir?", "o": ["y, l, m, n, r", "b, v, g, d", "p, t, k, s", "c, ç, j, ş"], "a": 0, "e": "y, l, m, n, r sonor samitlərdir — kar qarşılığı yoxdur."}, {"s": "Cingiltili qarşılığı olmayan kar samit hansıdır?", "o": ["p", "t", "h", "ş"], "a": 2, "e": "h samitinin cingiltili qarşılığı yoxdur. p-b, t-d, ş-j cütlük təşkil edir."}, {"s": "«Məktəb» sözü neçə hecadan ibarətdir?", "o": ["1", "2", "3", "4"], "a": 1, "e": "mək-təb — 2 heca. Hecaların sayı saitlərin sayına bərabərdir."}, {"s": "«Müəllim» sözü neçə hecadan ibarətdir?", "o": ["2", "3", "4", "5"], "a": 1, "e": "mü-əl-lim — 3 heca, çünki sözdə 3 sait var."}, {"s": "Azərbaycan dilində vurğu əsasən hansı hecanın üzərinə düşür?", "o": ["Birinci heca", "İkinci heca", "Son heca", "Sondan əvvəlki heca"], "a": 2, "e": "Azərbaycan dilində vurğu əsas etibarilə son hecaya düşür."}, {"s": "Hansı söz ahəng qanununa tabe deyil?", "o": ["qapılar", "uşaqlar", "kitab", "gözlük"], "a": 2, "e": "«Kitab» sözündə həm incə (i), həm qalın (a) sait var — ahəng qanununa tabe deyil. Alınma sözdür."}, {"s": "Sait səslə bitən sözə sait səslə başlayan şəkilçi artırılarkən hansı bitişdirici samitlərdən istifadə olunur?", "o": ["y, n, s", "b, d, g", "k, q, x", "l, m, r"], "a": 0, "e": "Bitişdirici samitlər: y, n, s. Məsələn: ata-s-ı, ata-y-a, ev-i-n-in."}, {"s": "«Ağız» sözünə mənsubiyyət şəkilçisi artırıldıqda hansı fonetik hadisə baş verir?", "o": ["Saitin artması", "Saitin düşməsi", "Samitin artması", "Heç bir dəyişiklik olmur"], "a": 1, "e": "ağız → ağzı. İkinci hecadakı sait düşür. Eyni hadisə: burun → burnu, oğul → oğlu."}, {"s": "«Çörək» sözünə «-i» şəkilçisi artırıldıqda son samit necə dəyişir?", "o": ["k → g", "k → y", "k → q", "Dəyişmir"], "a": 1, "e": "çörək → çörəyi. Söz sonundakı «k» saitlə başlayan şəkilçi qarşısında «y»-yə çevrilir."}, {"s": "«Palıd» sözünün sonundakı «d» samiti necə tələffüz olunur?", "o": ["d kimi", "t kimi", "z kimi", "s kimi"], "a": 1, "e": "Söz sonunda cingiltili samitlər karlaşır: palıd [palıt], kitab [kitap]."}, {"s": "Hansı sözdə qoşa samit var?", "o": ["dost", "hiss", "üst", "səs"], "a": 1, "e": "«Hiss» sözündə qoşa «s» samiti var. Digərlərində iki müxtəlif samit yanaşıdır."}, {"s": "«Ailə» sözü neçə hecadan ibarətdir?", "o": ["2", "3", "4", "1"], "a": 1, "e": "a-i-lə — 3 heca, 3 sait var."}]$q$::jsonb from public.items where slug='fonetika'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

insert into public.items (slug,kind,subject,title,subtitle,sort,price,question_count,minutes,mode) values ('ismin-hallari','topic','azerbaycan-dili','İsmin halları','Altı hal, şəkilçilər, müəyyən və qeyri-müəyyən formalar · 18 sual',2,0,18,0,'learn')
  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,$q$<h3>Hal nədir?</h3>
<p>İsmin halı onun cümlədəki digər sözlərlə əlaqəsini göstərir. Azərbaycan dilində altı hal var.</p>

<div class="tscroll"><table>
<tr><th>Hal</th><th>Sualları</th><th>Şəkilçiləri</th><th>Nümunə</th></tr>
<tr><td>Adlıq</td><td>kim? nə? hara?</td><td>yoxdur</td><td>uşaq, kitab</td></tr>
<tr><td>Yiyəlik</td><td>kimin? nəyin? haranın?</td><td>-ın, -in, -un, -ün</td><td>uşağın kitabı</td></tr>
<tr><td>Yönlük</td><td>kimə? nəyə? haraya?</td><td>-a, -ə (-ya, -yə)</td><td>məktəbə getdim</td></tr>
<tr><td>Təsirlik</td><td>kimi? nəyi? haranı?</td><td>-ı, -i, -u, -ü</td><td>kitabı oxudum</td></tr>
<tr><td>Yerlik</td><td>kimdə? nədə? harada?</td><td>-da, -də</td><td>bağçada oynayır</td></tr>
<tr><td>Çıxışlıq</td><td>kimdən? nədən? haradan?</td><td>-dan, -dən</td><td>şəhərdən gəldim</td></tr>
</table></div>

<h3>Müəyyən və qeyri-müəyyən forma</h3>
<p>Yiyəlik və təsirlik hal iki formada olur. Şəkilçi varsa müəyyən, yoxdursa qeyri-müəyyən formadır:</p>
<div class="ex">
<b>Kitab</b> oxudum — qeyri-müəyyən təsirlik (hansı kitab olduğu bilinmir).<br>
<b>Kitabı</b> oxudum — müəyyən təsirlik (konkret kitab).
</div>

<h3>Şəkilçilərin ardıcıllığı</h3>
<p>İsmə bir neçə şəkilçi artırılarkən ardıcıllıq dəyişmir:</p>
<div class="ex">kök → cəm → mənsubiyyət → hal<br>
<b>dost</b> + <b>lar</b> + <b>ımız</b> + <b>dan</b> = dostlarımızdan</div>

<h3>Hallar cümlədə hansı üzv olur?</h3>
<ul>
<li><b>Adlıq hal</b> — adətən mübtəda: «<i>Uşaq</i> gəldi.»</li>
<li><b>Təsirlik hal</b> — vasitəsiz tamamlıq: «Kitabı oxudum.»</li>
<li><b>Yönlük, yerlik, çıxışlıq</b> — vasitəli tamamlıq və ya zərflik: «Dostuma yazdım», «Evdə qaldım»</li>
<li><b>Yiyəlik hal</b> — III növ təyini söz birləşməsinin birinci tərəfi: «evin qapısı»</li>
</ul>

<h3>Tez-tez buraxılan səhv</h3>
<p>Yerlik və çıxışlıq halı qarışdırmaq olmaz: yerlik hal <b>harada</b> olduğunu, çıxışlıq hal
<b>haradan</b> gəldiyini bildirir.</p>$q$,$q$[{"s": "İsmin neçə halı var?", "o": ["4", "5", "6", "7"], "a": 2, "e": "Adlıq, yiyəlik, yönlük, təsirlik, yerlik, çıxışlıq — 6 hal."}, {"s": "«Kitabı oxudum» cümləsində «kitabı» sözü hansı haldadır?", "o": ["Adlıq", "Təsirlik", "Yönlük", "Yiyəlik"], "a": 1, "e": "Təsirlik hal «kimi? nəyi?» sualına cavab verir."}, {"s": "«Məktəbə gedirəm» cümləsində «məktəbə» sözü hansı haldadır?", "o": ["Yönlük", "Yerlik", "Çıxışlıq", "Təsirlik"], "a": 0, "e": "Yönlük hal «kimə? nəyə? haraya?» sualına cavab verir, şəkilçiləri -a, -ə."}, {"s": "Yiyəlik hal hansı suallara cavab verir?", "o": ["Kimi? Nəyi?", "Kimin? Nəyin?", "Kimdə? Nədə?", "Kimə? Nəyə?"], "a": 1, "e": "Yiyəlik hal: kimin? nəyin? haranın?"}, {"s": "«Şəhərdən gəldim» cümləsində «şəhərdən» sözü hansı haldadır?", "o": ["Yerlik", "Çıxışlıq", "Yönlük", "Adlıq"], "a": 1, "e": "Çıxışlıq hal: kimdən? nədən? haradan? Şəkilçiləri -dan, -dən."}, {"s": "Adlıq halın şəkilçisi varmı?", "o": ["Bəli, -ı/-i", "Bəli, -da/-də", "Xeyr, şəkilçisizdir", "Bəli, -ın/-in"], "a": 2, "e": "Adlıq hal sözün lüğət formasıdır, şəkilçi qəbul etmir."}, {"s": "Yerlik halın şəkilçiləri hansılardır?", "o": ["-da, -də", "-dan, -dən", "-a, -ə", "-ın, -in"], "a": 0, "e": "Yerlik hal: -da, -də. Sual: kimdə? nədə? harada?"}, {"s": "«Bağçada uşaqlar oynayır» cümləsində «bağçada» sözü hansı haldadır?", "o": ["Çıxışlıq", "Yerlik", "Yönlük", "Təsirlik"], "a": 1, "e": "«Harada?» sualına cavab verir — yerlik hal."}, {"s": "Çıxışlıq hal hansı suallara cavab verir?", "o": ["Kimə? Nəyə?", "Kimdə? Nədə?", "Kimdən? Nədən?", "Kimin? Nəyin?"], "a": 2, "e": "Çıxışlıq hal: kimdən? nədən? haradan?"}, {"s": "«Atanın kitabı» birləşməsində «atanın» sözü hansı haldadır?", "o": ["Adlıq", "Yiyəlik", "Təsirlik", "Yerlik"], "a": 1, "e": "«Kimin?» sualına cavab verir — yiyəlik hal, şəkilçisi -nın."}, {"s": "Təsirlik halın şəkilçiləri hansılardır?", "o": ["-da, -də", "-ı, -i, -u, -ü", "-a, -ə", "-dan, -dən"], "a": 1, "e": "Təsirlik hal: -ı, -i, -u, -ü; saitlə bitən sözlərdə -nı, -ni, -nu, -nü."}, {"s": "Yönlük halın şəkilçiləri hansılardır?", "o": ["-a, -ə", "-da, -də", "-ın, -in", "-ı, -i"], "a": 0, "e": "Yönlük hal: -a, -ə; saitlə bitən sözlərdə -ya, -yə."}, {"s": "«Su içdim» cümləsində «su» sözü hansı haldadır?", "o": ["Adlıq hal", "Qeyri-müəyyən təsirlik hal", "Yönlük hal", "Yiyəlik hal"], "a": 1, "e": "«Nə içdim?» — su. Şəkilçi qəbul etməsə də, təsirlik haldadır (qeyri-müəyyən forma)."}, {"s": "İsmin hansı halı sözün ilkin, lüğət formasıdır?", "o": ["Yiyəlik", "Adlıq", "Təsirlik", "Yerlik"], "a": 1, "e": "Adlıq hal ismin başlanğıc formasıdır."}, {"s": "Mübtəda adətən hansı halda olur?", "o": ["Təsirlik", "Yönlük", "Adlıq", "Çıxışlıq"], "a": 2, "e": "Mübtəda adlıq halda olur: «Uşaq gəldi»."}, {"s": "Vasitəsiz tamamlıq hansı halda olur?", "o": ["Yönlük", "Təsirlik", "Yerlik", "Çıxışlıq"], "a": 1, "e": "Vasitəsiz tamamlıq təsirlik halda olur və təsirli feilə aid edilir."}, {"s": "«Ev qapısı» birləşməsində «ev» sözü hansı haldadır?", "o": ["Adlıq hal", "Qeyri-müəyyən yiyəlik hal", "Yerlik hal", "Təsirlik hal"], "a": 1, "e": "II növ təyini söz birləşməsində birinci tərəf qeyri-müəyyən yiyəlik haldadır."}, {"s": "Hansı cərgədə ismin halları düzgün ardıcıllıqla verilib?", "o": ["Adlıq, təsirlik, yiyəlik, yönlük, yerlik, çıxışlıq", "Adlıq, yiyəlik, yönlük, təsirlik, yerlik, çıxışlıq", "Yiyəlik, adlıq, yönlük, yerlik, təsirlik, çıxışlıq", "Adlıq, yönlük, yiyəlik, təsirlik, çıxışlıq, yerlik"], "a": 1, "e": "Düzgün ardıcıllıq: adlıq, yiyəlik, yönlük, təsirlik, yerlik, çıxışlıq."}]$q$::jsonb from public.items where slug='ismin-hallari'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

