  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Sözün leksik mənasını öyrənən dilçilik şöbəsi necə adlanır?", "o": ["Fonetika", "Leksikologiya", "Morfologiya", "Sintaksis"], "a": 1, "e": "Leksikologiya sözün mənasını və lüğət tərkibini öyrənir."}, {"s": "Mənaca yaxın olan sözlər necə adlanır?", "o": ["Antonim", "Omonim", "Sinonim", "Termin"], "a": 2, "e": "Sinonimlər mənaca yaxın, lakin fərqli sözlərdir: gözəl — qəşəng — göyçək."}, {"s": "Mənaca bir-birinin əksi olan sözlər necə adlanır?", "o": ["Sinonim", "Antonim", "Omonim", "Arxaizm"], "a": 1, "e": "Antonimlər əks mənalı sözlərdir: isti — soyuq, böyük — kiçik."}, {"s": "Yazılışı və tələffüzü eyni, mənası fərqli olan sözlər necə adlanır?", "o": ["Omonim", "Sinonim", "Antonim", "Neologizm"], "a": 0, "e": "Omonim: «üz» (sifət), «üz» (üzmək feili), «üz» (süd üzü)."}, {"s": "Hansı cərgədə antonim cütlüyü verilib?", "o": ["gözəl — qəşəng", "ağıllı — dərrakəli", "uzun — qısa", "böyük — iri"], "a": 2, "e": "«Uzun» və «qısa» əks mənalı sözlərdir; digərləri sinonimdir."}, {"s": "«Dilə tutmaq» ifadəsi nədir?", "o": ["Sərbəst birləşmə", "Frazeoloji birləşmə", "Termin", "Mürəkkəb söz"], "a": 1, "e": "Frazeoloji birləşmə bütöv halda məcazi məna bildirir: «dilə tutmaq» = razı salmaq."}, {"s": "Dildə işlənməyən, köhnəlmiş sözlər necə adlanır?", "o": ["Neologizm", "Arxaizm", "Termin", "Dialekt"], "a": 1, "e": "Arxaizmlər köhnəlmiş sözlərdir: ərəbxana, sərkərdə, bəy."}, {"s": "Dilə yeni daxil olan sözlər necə adlanır?", "o": ["Arxaizm", "Dialekt", "Neologizm", "Omonim"], "a": 2, "e": "Neologizmlər yeni yaranmış və ya yeni alınmış sözlərdir."}, {"s": "Yalnız müəyyən bölgədə işlənən sözlər necə adlanır?", "o": ["Termin", "Dialekt sözləri", "Ümumişlək sözlər", "Alınma sözlər"], "a": 1, "e": "Dialekt sözləri yerli şivələrə aiddir və ədəbi dilin normasına daxil deyil."}, {"s": "Elmin müəyyən sahəsinə aid dəqiq mənalı sözlər necə adlanır?", "o": ["Termin", "Frazeologizm", "Sinonim", "Arxaizm"], "a": 0, "e": "Terminlər çoxmənalı olmur: tənlik, fonem, hüceyrə."}, {"s": "Bir neçə mənada işlənə bilən sözlər necə adlanır?", "o": ["Təkmənalı sözlər", "Çoxmənalı sözlər", "Omonimlər", "Antonimlər"], "a": 1, "e": "Çoxmənalı sözün mənaları bir-biri ilə bağlıdır: «baş» — bədən üzvü, rəhbər, başlanğıc."}, {"s": "«Dağın ətəyi» birləşməsində «ətək» sözü hansı mənada işlənib?", "o": ["Həqiqi", "Məcazi", "Termin", "Omonim"], "a": 1, "e": "Söz öz ilkin mənasından çıxıb məcazi mənada — «aşağı hissə» — işlənib."}, {"s": "Hansı söz alınma sözdür?", "o": ["dağ", "çörək", "kompüter", "quş"], "a": 2, "e": "«Kompüter» başqa dildən alınmış sözdür."}, {"s": "«Ürəyi yanmaq» ifadəsinin mənası nədir?", "o": ["Xəstələnmək", "Yazığı gəlmək, mərhəmət etmək", "Qorxmaq", "Sevinmək"], "a": 1, "e": "Frazeoloji birləşmədir, hərfi mənada başa düşülmür."}, {"s": "Hansı cərgədə sinonimlər verilib?", "o": ["isti — soyuq", "cəsur — qorxaq", "sevinc — fərəh", "gecə — gündüz"], "a": 2, "e": "«Sevinc» və «fərəh» mənaca yaxındır. Qalanları antonimdir."}, {"s": "Lüğət tərkibi dedikdə nə başa düşülür?", "o": ["Dildəki bütün səslər", "Dildəki bütün sözlər", "Dildəki bütün şəkilçilər", "Dildəki bütün cümlələr"], "a": 1, "e": "Lüğət tərkibi dilin bütün söz ehtiyatıdır."}, {"s": "Hansı söz omonim ola bilər?", "o": ["kitab", "yaz", "ağac", "pəncərə"], "a": 1, "e": "«Yaz» — fəsil adı və «yazmaq» feilinin əmr forması. İki fərqli məna, eyni yazılış."}, {"s": "Frazeoloji birləşmələrin əsas xüsusiyyəti nədir?", "o": ["Hər sözü ayrıca mənalıdır", "Bütöv halda bir məna bildirir", "Həmişə iki sözdən ibarətdir", "Yalnız şeirdə işlənir"], "a": 1, "e": "Frazeologizm sabit birləşmədir, mənası tərkib hissələrinin cəmindən çıxmır."}]$q$::jsonb from public.items where slug='leksika'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

