insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Quruluşuna görə sözlər neçə yerə bölünür?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Sadə, düzəltmə və mürəkkəb sözlər — 3 növ."}, {"s": "«Dəmirçi» sözü quruluşuna görə necədir?", "o": ["Sadə", "Düzəltmə", "Mürəkkəb", "Alınma"], "a": 1, "e": "Kök (dəmir) + leksik şəkilçi (-çi) = düzəltmə söz."}, {"s": "«Günəbaxan» sözü quruluşuna görə necədir?", "o": ["Sadə", "Düzəltmə", "Mürəkkəb", "Təkhecalı"], "a": 2, "e": "İki kökün birləşməsindən yaranıb: gün + ə + baxan."}, {"s": "«Kitab» sözü quruluşuna görə necədir?", "o": ["Sadə", "Düzəltmə", "Mürəkkəb", "Qoşa"], "a": 0, "e": "Yalnız kökdən ibarətdir, şəkilçi qəbul etməyib."}, {"s": "Yeni söz yaradan şəkilçilər necə adlanır?", "o": ["Qrammatik şəkilçilər", "Leksik şəkilçilər", "Hal şəkilçiləri", "Şəxs şəkilçiləri"], "a": 1, "e": "Leksik (sözdüzəldici) şəkilçilər yeni söz yaradır: -çı, -lıq, -lı, -sız."}, {"s": "Sözün formasını dəyişən, yeni söz yaratmayan şəkilçilər necə adlanır?", "o": ["Leksik", "Qrammatik", "Sözdüzəldici", "Kök"], "a": 1, "e": "Qrammatik (sözdəyişdirici) şəkilçilər: hal, mənsubiyyət, cəm, şəxs şəkilçiləri."}, {"s": "«-lıq, -lik, -luq, -lük» şəkilçisi hansı növə aiddir?", "o": ["Qrammatik", "Leksik", "Hal şəkilçisi", "Şəxs şəkilçisi"], "a": 1, "e": "Yeni söz yaradır: dost → dostluq, göz → gözlük."}, {"s": "«Uşaqlar» sözündə «-lar» şəkilçisi hansı növdəndir?", "o": ["Leksik", "Qrammatik", "Sözdüzəldici", "Kök"], "a": 1, "e": "Cəm şəkilçisi qrammatik şəkilçidir, yeni söz yaratmır."}, {"s": "Hansı söz düzəltmə sözdür?", "o": ["su", "sulu", "dağ", "ev"], "a": 1, "e": "su + -lu = sulu. Kök + leksik şəkilçi."}, {"s": "Hansı söz mürəkkəb sözdür?", "o": ["dəmirçi", "otaq", "boyunbağı", "yazıçı"], "a": 2, "e": "«Boyunbağı» iki kökdən ibarətdir: boyun + bağı."}, {"s": "Sözün mənalı hissələrə bölünməyən əsas hissəsi necə adlanır?", "o": ["Şəkilçi", "Kök", "Son", "Vurğu"], "a": 1, "e": "Kök sözün əsas mənasını daşıyan, bölünməyən hissəsidir."}, {"s": "«Dostluq» sözündə kök hansıdır?", "o": ["dostluq", "dost", "luq", "do"], "a": 1, "e": "Kök «dost», şəkilçi «-luq»."}, {"s": "Hansı cərgədə bütün sözlər düzəltmədir?", "o": ["qışlaq, baharat, kitab", "duzlu, işçi, gözlük", "qapı, pəncərə, divar", "göyqurşağı, dəvəquşu, boyunbağı"], "a": 1, "e": "duz+lu, iş+çi, göz+lük — hamısı kök + leksik şəkilçidir."}, {"s": "Mürəkkəb sözlər necə yaranır?", "o": ["Kök + şəkilçi", "İki və daha çox kökün birləşməsi", "Səslərin dəyişməsi", "Vurğunun yerdəyişməsi"], "a": 1, "e": "Mürəkkəb söz ən azı iki müstəqil kökdən əmələ gəlir."}, {"s": "«Qaragöz» sözü necə yaranıb?", "o": ["Kök + şəkilçi", "İki kökün birləşməsi", "Səs artımı", "Şəkilçi + kök"], "a": 1, "e": "qara + göz — mürəkkəb söz."}, {"s": "«Gözəllik» sözündə neçə şəkilçi var?", "o": ["1", "2", "3", "Şəkilçi yoxdur"], "a": 1, "e": "göz + əl + lik — «-əl» və «-lik» iki leksik şəkilçidir."}, {"s": "Hansı şəkilçi feildən isim düzəldir?", "o": ["-lar", "-ış/-iş", "-da/-də", "-ın/-in"], "a": 1, "e": "yaz → yazış, gör → görüş — feildən isim düzəldən leksik şəkilçidir."}, {"s": "Şəkilçilər söz kökünə nəzərən harada yerləşir?", "o": ["Əvvəlində", "Sonunda", "Ortasında", "Həm əvvəl, həm sonda"], "a": 1, "e": "Azərbaycan dilində şəkilçilər sözün sonuna artırılır — dil iltisaqi (aqqlütinativ) dildir."}]$q$::jsonb from public.items where slug='soz-yaradiciligi'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

