  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "İsim hansı suallara cavab verir?", "o": ["Necə? Nə cür?", "Kim? Nə? Hara?", "Nə etdi?", "Neçə? Nə qədər?"], "a": 1, "e": "İsim əşyanın adını bildirir: kim? nə? hara?"}, {"s": "İsimlər mənasına görə neçə yerə bölünür?", "o": ["Ümumi və xüsusi", "Sadə və düzəltmə", "Tək və cəm", "Konkret və mücərrəd"], "a": 0, "e": "Mənasına görə ümumi və xüsusi isimlər fərqləndirilir."}, {"s": "Hansı söz xüsusi isimdir?", "o": ["şəhər", "Bakı", "dağ", "çay"], "a": 1, "e": "Xüsusi isimlər konkret bir obyektin adıdır və böyük hərflə yazılır."}, {"s": "Xüsusi isimlər necə yazılır?", "o": ["Kiçik hərflə", "Böyük hərflə", "Dırnaq içində", "Defislə"], "a": 1, "e": "Xüsusi isimlər həmişə böyük hərflə başlanır: Nizami, Gəncə, Kür."}, {"s": "Hansı söz mücərrəd isimdir?", "o": ["stol", "sevinc", "ağac", "kitab"], "a": 1, "e": "Mücərrəd isimlər duyğu üzvləri ilə qavranılmayan anlayışları bildirir: sevinc, qorxu, fikir."}, {"s": "İsimlərin cəm şəkilçiləri hansılardır?", "o": ["-lı, -li", "-lar, -lər", "-çı, -çi", "-da, -də"], "a": 1, "e": "Cəm şəkilçisi: -lar (qalın saitli sözlərdə), -lər (incə saitli sözlərdə)."}, {"s": "«Kitabım» sözündə «-ım» hansı şəkilçidir?", "o": ["Hal şəkilçisi", "Mənsubiyyət şəkilçisi", "Cəm şəkilçisi", "Xəbərlik şəkilçisi"], "a": 1, "e": "Mənsubiyyət şəkilçisi əşyanın kimə aid olduğunu bildirir: kitabım, kitabın, kitabı."}, {"s": "«Mən tələbəyəm» cümləsində «-yəm» hansı şəkilçidir?", "o": ["Mənsubiyyət", "Xəbərlik", "Hal", "Cəm"], "a": 1, "e": "Xəbərlik şəkilçiləri ismi xəbərə çevirir: -am/-əm, -san/-sən, -dır/-dir."}, {"s": "İsmin qrammatik kateqoriyaları hansılardır?", "o": ["Kəmiyyət, mənsubiyyət, hal, xəbərlik", "Zaman, şəxs, növ", "Dərəcə, kəmiyyət", "Şəkil, zaman, növ"], "a": 0, "e": "İsmə aid dörd kateqoriya: kəmiyyət (tək-cəm), mənsubiyyət, hal və xəbərlik."}, {"s": "Hansı söz konkret isimdir?", "o": ["xoşbəxtlik", "arzu", "masa", "qorxu"], "a": 2, "e": "Konkret isimlər duyğu üzvləri ilə qavranılan əşyaları bildirir."}, {"s": "«Uşaqlar» sözü kəmiyyətcə necədir?", "o": ["Tək", "Cəm", "Mücərrəd", "Xüsusi"], "a": 1, "e": "Cəm şəkilçisi «-lar» qəbul edib."}, {"s": "Hansı cərgədə yalnız xüsusi isimlər var?", "o": ["Nizami, Kür, Şəki", "şəhər, çay, dağ", "kitab, Bakı, su", "Araz, meşə, ev"], "a": 0, "e": "Nizami (şəxs adı), Kür (çay adı), Şəki (şəhər adı) — hamısı xüsusi isimdir."}, {"s": "Mənsubiyyətə görə dəyişən isimlər neçə şəxs üzrə dəyişir?", "o": ["2", "3", "6", "4"], "a": 1, "e": "Üç şəxs üzrə, tək və cəmdə: kitabım, kitabın, kitabı; kitabımız, kitabınız, kitabları."}, {"s": "«Şagird» sözü quruluşuna görə necədir?", "o": ["Sadə", "Düzəltmə", "Mürəkkəb", "Qoşa"], "a": 0, "e": "Kökdən ibarətdir, şəkilçi qəbul etməyib."}, {"s": "İsimlər cümlədə ən çox hansı vəzifədə işlənir?", "o": ["Yalnız xəbər", "Yalnız təyin", "Mübtəda və tamamlıq", "Yalnız zərflik"], "a": 2, "e": "İsim cümlənin istənilən üzvü ola bilər, lakin daha çox mübtəda və tamamlıq vəzifəsində çıxış edir."}, {"s": "Hansı sözdə mənsubiyyət şəkilçisi var?", "o": ["evlər", "evdə", "evimiz", "evdən"], "a": 2, "e": "«-imiz» I şəxs cəmin mənsubiyyət şəkilçisidir."}, {"s": "«Dostlarımızdan» sözündə şəkilçilərin ardıcıllığı necədir?", "o": ["Hal, cəm, mənsubiyyət", "Cəm, mənsubiyyət, hal", "Mənsubiyyət, hal, cəm", "Cəm, hal, mənsubiyyət"], "a": 1, "e": "dost + lar (cəm) + ımız (mənsubiyyət) + dan (hal). Bu ardıcıllıq sabitdir."}, {"s": "Hansı isim quruluşuna görə mürəkkəbdir?", "o": ["gülüş", "dəvəquşu", "dostluq", "işçi"], "a": 1, "e": "dəvə + quşu — iki kökdən ibarətdir."}]$q$::jsonb from public.items where slug='isim'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

