  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Sifət hansı suallara cavab verir?", "o": ["Kim? Nə?", "Necə? Nə cür? Hansı?", "Nə etdi?", "Neçə?"], "a": 1, "e": "Sifət əşyanın əlamətini bildirir: necə? nə cür? hansı?"}, {"s": "Sifətin neçə dərəcəsi var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Adi, azaltma və çoxaltma dərəcəsi."}, {"s": "«Qıpqırmızı» sözü sifətin hansı dərəcəsindədir?", "o": ["Adi", "Azaltma", "Çoxaltma", "Müqayisə"], "a": 2, "e": "Qoşa təkrarla yaranan çoxaltma dərəcəsidir: qıpqırmızı, yamyaşıl, gömgöy."}, {"s": "«Göyümsov» sözü sifətin hansı dərəcəsindədir?", "o": ["Adi", "Azaltma", "Çoxaltma", "Üstünlük"], "a": 1, "e": "Azaltma dərəcəsi əlamətin zəif olduğunu bildirir: -ımtıl, -sov, -şın, -raq."}, {"s": "Hansı şəkilçi sifətin azaltma dərəcəsini düzəldir?", "o": ["-lı, -li", "-ımtıl, -imtil", "-çı, -çi", "-lar, -lər"], "a": 1, "e": "Azaltma dərəcəsi şəkilçiləri: -ımtıl, -sov, -şın, -raq."}, {"s": "Çoxaltma dərəcəsi hansı sözlərlə də düzəlir?", "o": ["ən, lap, çox", "bir az, azca", "də, da", "ki, ha"], "a": 0, "e": "«Ən gözəl», «lap uca», «çox maraqlı» — analitik yolla çoxaltma dərəcəsi."}, {"s": "Sifətlər əsli və nisbi olmaqla neçə yerə bölünür?", "o": ["2", "3", "4", "5"], "a": 0, "e": "Mənasına görə əsli (keyfiyyət) və nisbi sifətlər fərqləndirilir."}, {"s": "Hansı söz əsli sifətdir?", "o": ["dəmir (qapı)", "gözəl", "daşlı", "şəhər (həyatı)"], "a": 1, "e": "Əsli sifətlər əşyanın daxili keyfiyyətini bildirir və dərəcə üzrə dəyişir."}, {"s": "«Daşlı yol» birləşməsində «daşlı» sözü quruluşuna görə necədir?", "o": ["Sadə", "Düzəltmə", "Mürəkkəb", "Qoşa"], "a": 1, "e": "daş + -lı — düzəltmə sifətdir."}, {"s": "Sifət cümlədə ən çox hansı vəzifədə işlənir?", "o": ["Mübtəda", "Təyin", "Tamamlıq", "Zərflik"], "a": 1, "e": "Sifət isimdən əvvəl gələrək onun əlamətini bildirir — təyin olur."}, {"s": "Hansı şəkilçi isimdən sifət düzəldir?", "o": ["-lar, -lər", "-lı, -li, -lu, -lü", "-da, -də", "-ıb, -ib"], "a": 1, "e": "duz → duzlu, ağıl → ağıllı — isimdən sifət düzəldən şəkilçidir."}, {"s": "«Sarımtıl» sözündə hansı dərəcə var?", "o": ["Adi", "Azaltma", "Çoxaltma", "Üstünlük"], "a": 1, "e": "«-ımtıl» azaltma dərəcəsi şəkilçisidir — rəngin tam olmadığını bildirir."}, {"s": "Sifətin isimləşməsi nə deməkdir?", "o": ["Sifətin feilə çevrilməsi", "Sifətin isim kimi işlənməsi", "Sifətin zərfə çevrilməsi", "Sifətin qısalması"], "a": 1, "e": "«Yaxşılar gəldi» — «yaxşı» sifəti burada isim kimi işlənib, cəm şəkilçisi qəbul edib."}, {"s": "Hansı cərgədə yalnız sifət var?", "o": ["kitab, dəftər, qələm", "uca, enli, dərin", "gəldi, getdi, oxudu", "beş, on, iyirmi"], "a": 1, "e": "uca, enli, dərin — əlamət bildirən sözlərdir."}, {"s": "«Yamyaşıl» sözü necə yaranıb?", "o": ["Şəkilçi ilə", "İlk hecanın təkrarı ilə", "İki kökün birləşməsi ilə", "Səs düşümü ilə"], "a": 1, "e": "Çoxaltma dərəcəsi ilk hecanın «m» samiti ilə təkrarından yaranıb: ya-m-yaşıl."}, {"s": "Nisbi sifətlər dərəcə üzrə dəyişirmi?", "o": ["Bəli, həmişə", "Xeyr, dəyişmir", "Yalnız cəmdə dəyişir", "Yalnız şeirdə dəyişir"], "a": 1, "e": "Nisbi sifətlər (dəmir qapı, şəhər havası) əlamətin azlığını-çoxluğunu bildirmir."}, {"s": "«Ən çalışqan şagird» birləşməsində hansı dərəcə var?", "o": ["Adi", "Azaltma", "Çoxaltma", "Dərəcə yoxdur"], "a": 2, "e": "«Ən» sözü ilə çoxaltma (üstünlük) dərəcəsi yaranır."}, {"s": "Hansı söz sifətin adi dərəcəsindədir?", "o": ["qapqara", "qaramtıl", "qara", "ən qara"], "a": 2, "e": "Adi dərəcə əlaməti olduğu kimi, artırma və ya azaltma olmadan bildirir."}]$q$::jsonb from public.items where slug='sifet'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

insert into public.items (slug,kind,subject,title,subtitle,sort,price,question_count,minutes,mode) values ('say-evezlik','topic','azerbaycan-dili','Say və əvəzlik','Miqdar, sıra, kəsr sayları; əvəzliyin altı növü · 18 sual',7,2.0,18,0,'learn')
  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Say hansı suallara cavab verir?", "o": ["Kim? Nə?", "Necə?", "Neçə? Nə qədər? Neçənci?", "Harada?"], "a": 2, "e": "Say əşyanın miqdarını və sırasını bildirir."}, {"s": "Saylar neçə yerə bölünür?", "o": ["Miqdar və sıra sayları", "Tək və cəm", "Sadə və mürəkkəb", "Əsli və nisbi"], "a": 0, "e": "Mənasına görə miqdar və sıra sayları fərqləndirilir."}, {"s": "«Beşinci sinif» birləşməsində «beşinci» hansı saydır?", "o": ["Miqdar", "Sıra", "Kəsr", "Qeyri-müəyyən"], "a": 1, "e": "«-ıncı, -inci, -uncu, -üncü» sıra sayı şəkilçiləridir."}, {"s": "«Xeyli adam gəldi» cümləsində «xeyli» hansı saydır?", "o": ["Müəyyən miqdar", "Qeyri-müəyyən miqdar", "Sıra", "Kəsr"], "a": 1, "e": "Qeyri-müəyyən miqdar sayları dəqiq rəqəm bildirmir: az, çox, xeyli, bir neçə."}, {"s": "«Beşdə iki» ifadəsi hansı say növüdür?", "o": ["Sıra sayı", "Kəsr sayı", "Qeyri-müəyyən say", "Müəyyən miqdar sayı"], "a": 1, "e": "Kəsr sayları hissəni bildirir və yerlik hal şəkilçisi ilə düzəlir."}, {"s": "Saylardan sonra gələn isim adətən hansı kəmiyyətdə olur?", "o": ["Cəmdə", "Təkdə", "Həm tək, həm cəmdə", "Mənsubiyyətli"], "a": 1, "e": "«Beş kitab» deyilir, «beş kitablar» yox — saydan sonra isim təkdə işlənir."}, {"s": "Əvəzlik nədir?", "o": ["Əşyanın adını bildirən söz", "İsim, sifət, say və zərfləri əvəz edən söz", "Hərəkət bildirən söz", "Əlamət bildirən söz"], "a": 1, "e": "Əvəzlik başqa nitq hissələrini əvəz edir, özü isə konkret məna bildirmir."}, {"s": "Əvəzliyin neçə növü var?", "o": ["3", "4", "5", "6"], "a": 3, "e": "Şəxs, işarə, sual, qeyri-müəyyən, təyini və qayıdış əvəzlikləri."}, {"s": "«Mən, sən, o, biz, siz, onlar» hansı əvəzliklərdir?", "o": ["İşarə", "Şəxs", "Sual", "Təyini"], "a": 1, "e": "Şəxs əvəzlikləri ünsiyyət iştirakçılarını bildirir."}, {"s": "«Bu, o, elə, belə, həmin» hansı əvəzliklərdir?", "o": ["Şəxs", "İşarə", "Qeyri-müəyyən", "Qayıdış"], "a": 1, "e": "İşarə əvəzlikləri əşyanı göstərir."}, {"s": "«Kim, nə, hansı, neçə» hansı əvəzliklərdir?", "o": ["Sual", "İşarə", "Təyini", "Qayıdış"], "a": 0, "e": "Sual əvəzlikləri sual məqsədi ilə işlənir."}, {"s": "«Kimsə, nəsə, bəzi, filan» hansı əvəzliklərdir?", "o": ["Təyini", "Qeyri-müəyyən", "İşarə", "Şəxs"], "a": 1, "e": "Qeyri-müəyyən əvəzliklər naməlum əşya və şəxsi bildirir."}, {"s": "«Öz» sözü hansı əvəzlikdir?", "o": ["Şəxs", "İşarə", "Qayıdış", "Sual"], "a": 2, "e": "Qayıdış əvəzliyi hərəkətin icraçıya aid olduğunu bildirir: özüm, özün, özü."}, {"s": "«Hamı, hər, bütün» hansı əvəzliklərdir?", "o": ["Təyini", "Qeyri-müəyyən", "Sual", "İşarə"], "a": 0, "e": "Təyini əvəzliklər ümumilik, bütövlük bildirir."}, {"s": "Şəxs əvəzlikləri hansı kateqoriyalar üzrə dəyişir?", "o": ["Zaman və növ", "Hal və kəmiyyət", "Dərəcə", "Şəkil"], "a": 1, "e": "Şəxs əvəzlikləri hallanır və tək-cəmdə işlənir: mən — məni — mənə; biz — bizi."}, {"s": "«İki» sözü hansı say növünə aiddir?", "o": ["Sıra sayı", "Müəyyən miqdar sayı", "Kəsr sayı", "Qeyri-müəyyən say"], "a": 1, "e": "Dəqiq miqdar bildirir — müəyyən miqdar sayıdır."}, {"s": "Saylar rəqəmlə yazıldıqda sıra sayı necə göstərilir?", "o": ["Nöqtə ilə və ya şəkilçi ilə (5. və ya 5-ci)", "Vergüllə", "Mötərizədə", "Dırnaqda"], "a": 0, "e": "Sıra sayları rəqəmlə yazıldıqda «5-ci» və ya «5.» şəklində göstərilir."}, {"s": "Hansı cərgədə yalnız əvəzlik var?", "o": ["mən, bu, kim, öz", "beş, altı, yeddi", "gözəl, uca, dərin", "gəl, get, otur"], "a": 0, "e": "mən (şəxs), bu (işarə), kim (sual), öz (qayıdış) — hamısı əvəzlikdir."}]$q$::jsonb from public.items where slug='say-evezlik'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

