insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Feil hansı suallara cavab verir?", "o": ["Kim? Nə?", "Necə?", "Nə etdi? Nə edir? Nə edəcək?", "Neçə?"], "a": 2, "e": "Feil hərəkət və ya hal bildirir."}, {"s": "Feilin neçə şəkli var?", "o": ["4", "5", "6", "7"], "a": 2, "e": "Xəbər, əmr, arzu, şərt, vacib və lazım şəkli."}, {"s": "«Oxumalıyam» feili hansı şəkildədir?", "o": ["Xəbər", "Vacib", "Lazım", "Arzu"], "a": 1, "e": "«-malı, -məli» vacib şəklinin şəkilçisidir."}, {"s": "«Getsəm» feili hansı şəkildədir?", "o": ["Arzu", "Şərt", "Vacib", "Əmr"], "a": 1, "e": "«-sa, -sə» şərt şəklinin şəkilçisidir."}, {"s": "«Gələsiyəm» feili hansı şəkildədir?", "o": ["Vacib", "Lazım", "Şərt", "Arzu"], "a": 1, "e": "«-ası, -əsi» lazım şəklinin şəkilçisidir."}, {"s": "Feilin neçə növü var?", "o": ["3", "4", "5", "6"], "a": 2, "e": "Məlum, məchul, qayıdış, qarşılıq-birgəlik və icbar növü."}, {"s": "«Yazıldı» feili hansı növdədir?", "o": ["Məlum", "Məchul", "Qayıdış", "İcbar"], "a": 1, "e": "Məchul növdə iş görəni bilinmir, «-ıl, -il» şəkilçisi işlənir."}, {"s": "«Yazdırdı» feili hansı növdədir?", "o": ["Məlum", "Məchul", "İcbar", "Qayıdış"], "a": 2, "e": "İcbar növ işin başqasına gördürüldüyünü bildirir: «-dır, -dir»."}, {"s": "«Görüşdülər» feili hansı növdədir?", "o": ["Məchul", "Qayıdış", "Qarşılıq-birgəlik", "İcbar"], "a": 2, "e": "«-ış, -iş, -uş, -üş» qarşılıq-birgəlik növünün şəkilçisidir."}, {"s": "Təsirli feil nədir?", "o": ["Təsirlik halda tamamlıq tələb edən feil", "Yalnız keçmiş zamanda işlənən feil", "Əmr şəklindəki feil", "Məchul növdəki feil"], "a": 0, "e": "Təsirli feil «kimi? nəyi?» sualına cavab verən tamamlıq tələb edir: kitabı oxudu."}, {"s": "Hansı feil təsirsizdir?", "o": ["oxumaq", "yazmaq", "getmək", "görmək"], "a": 2, "e": "«Getmək» feili vasitəsiz tamamlıq qəbul etmir."}, {"s": "Feilin neçə zamanı var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Keçmiş, indiki və gələcək zaman."}, {"s": "«Gələcəyəm» feili hansı zamandadır?", "o": ["Keçmiş", "İndiki", "Qəti gələcək", "Qeyri-qəti gələcək"], "a": 2, "e": "«-acaq, -əcək» qəti gələcək zamanın şəkilçisidir."}, {"s": "«Gəlirəm» feili hansı zamandadır?", "o": ["Keçmiş", "İndiki", "Gələcək", "Şərt"], "a": 1, "e": "«-ır, -ir, -ur, -ür» indiki zamanın şəkilçisidir."}, {"s": "Şühudi keçmiş zamanın şəkilçisi hansıdır?", "o": ["-mış, -miş", "-dı, -di, -du, -dü", "-ır, -ir", "-acaq, -əcək"], "a": 1, "e": "Şühudi (qəti) keçmiş: gəldi, oxudu. Nəqli keçmiş: «-mış, -miş»."}, {"s": "Təsriflənməyən feillər hansılardır?", "o": ["Məsdər, feili sifət, feili bağlama", "Əmr, arzu, şərt", "Keçmiş, indiki, gələcək", "Məlum, məchul"], "a": 0, "e": "Bu üç forma şəxsə və zamana görə dəyişmir."}, {"s": "«Oxumaq» sözü feilin hansı formasıdır?", "o": ["Feili sifət", "Məsdər", "Feili bağlama", "Əmr"], "a": 1, "e": "«-maq, -mək» məsdər şəkilçisidir."}, {"s": "«Gələn adam» birləşməsində «gələn» hansı formadır?", "o": ["Məsdər", "Feili sifət", "Feili bağlama", "Sifət"], "a": 1, "e": "Feili sifət həm feil, həm sifət əlaməti daşıyır; «-an, -ən» şəkilçisi ilə düzəlir."}]$q$::jsonb from public.items where slug='feil'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

