  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Zərf hansı suallara cavab verir?", "o": ["Kim? Nə?", "Necə? Nə zaman? Harada? Niyə?", "Hansı?", "Neçə?"], "a": 1, "e": "Zərf hərəkətin tərzini, zamanını, yerini, səbəbini bildirir."}, {"s": "Zərfin neçə növü var?", "o": ["3", "4", "5", "6"], "a": 2, "e": "Tərzi-hərəkət, zaman, yer, miqdar (kəmiyyət) və səbəb-məqsəd zərfləri."}, {"s": "«Tez gəldi» cümləsində «tez» hansı zərfdir?", "o": ["Yer", "Zaman", "Tərzi-hərəkət", "Miqdar"], "a": 1, "e": "«Nə zaman?» sualına cavab verir."}, {"s": "«Sürətlə qaçdı» ifadəsində «sürətlə» hansı zərfdir?", "o": ["Tərzi-hərəkət", "Zaman", "Yer", "Səbəb"], "a": 0, "e": "«Necə?» sualına cavab verir — tərzi-hərəkət zərfidir."}, {"s": "«Qəsdən etdi» ifadəsində «qəsdən» hansı zərfdir?", "o": ["Zaman", "Yer", "Səbəb-məqsəd", "Miqdar"], "a": 2, "e": "«Nə üçün? Nə məqsədlə?» sualına cavab verir."}, {"s": "Köməkçi nitq hissələri hansılardır?", "o": ["İsim, sifət, say", "Qoşma, bağlayıcı, ədat, modal söz, nida", "Feil, zərf, əvəzlik", "Yalnız qoşma və bağlayıcı"], "a": 1, "e": "Köməkçi nitq hissələri müstəqil məna bildirmir, cümlə üzvü olmur."}, {"s": "«İlə, üçün, kimi, qədər» hansı köməkçi nitq hissəsidir?", "o": ["Bağlayıcı", "Qoşma", "Ədat", "Nida"], "a": 1, "e": "Qoşmalar isim və əvəzliklərdən sonra gələrək onların mənasını dəqiqləşdirir."}, {"s": "«Və, amma, lakin, ancaq» hansı köməkçi nitq hissəsidir?", "o": ["Qoşma", "Bağlayıcı", "Ədat", "Modal söz"], "a": 1, "e": "Bağlayıcılar söz və cümlələri bir-birinə bağlayır."}, {"s": "«Ki, da, də, belə, hətta» hansı köməkçi nitq hissəsidir?", "o": ["Ədat", "Qoşma", "Nida", "Bağlayıcı"], "a": 0, "e": "Ədatlar sözün və cümlənin mənasını qüvvətləndirir."}, {"s": "«Əlbəttə, görünür, şübhəsiz» hansı köməkçi nitq hissəsidir?", "o": ["Ədat", "Nida", "Modal söz", "Qoşma"], "a": 2, "e": "Modal sözlər danışanın fikrə münasibətini bildirir."}, {"s": "«Ah, oh, vay, afərin» hansı köməkçi nitq hissəsidir?", "o": ["Nida", "Ədat", "Modal söz", "Bağlayıcı"], "a": 0, "e": "Nidalar hiss və həyəcanı ifadə edir."}, {"s": "Köməkçi nitq hissələri cümlə üzvü ola bilərmi?", "o": ["Bəli, həmişə", "Xeyr, ola bilməz", "Yalnız qoşmalar ola bilər", "Yalnız şeirdə ola bilər"], "a": 1, "e": "Köməkçi nitq hissələri müstəqil cümlə üzvü olmur."}, {"s": "Qoşmalar hansı hallarla işlənir?", "o": ["Yalnız adlıq halla", "Adlıq, yiyəlik, yönlük, çıxışlıq hallarla", "Yalnız yerlik halla", "Heç bir halla"], "a": 1, "e": "Məsələn: «kitab kimi» (adlıq), «mənim üçün» (yiyəlik), «evə doğru» (yönlük), «səhərdən bəri» (çıxışlıq)."}, {"s": "Hansı söz zərfdir?", "o": ["gözəl (qız)", "dünən", "kitab", "oxumaq"], "a": 1, "e": "«Dünən» zaman zərfidir, hərəkətin nə zaman icra olunduğunu bildirir."}, {"s": "«Çox danışdı» ifadəsində «çox» hansı zərfdir?", "o": ["Zaman", "Yer", "Miqdar", "Səbəb"], "a": 2, "e": "«Nə qədər?» sualına cavab verir — miqdar zərfidir."}, {"s": "«İrəli getdi» ifadəsində «irəli» hansı zərfdir?", "o": ["Yer", "Zaman", "Tərz", "Miqdar"], "a": 0, "e": "«Hara?» sualına cavab verir — yer zərfidir."}, {"s": "Bağlayıcılar neçə yerə bölünür?", "o": ["Tabesizlik və tabelilik bağlayıcıları", "Sadə və mürəkkəb", "Tək və cəm", "Əsli və nisbi"], "a": 0, "e": "Tabesizlik bağlayıcıları (və, amma) bərabərhüquqlu, tabelilik bağlayıcıları (ki, çünki) asılı hissələri bağlayır."}, {"s": "Zərf cümlədə hansı vəzifədə işlənir?", "o": ["Mübtəda", "Təyin", "Zərflik", "Tamamlıq"], "a": 2, "e": "Zərf əsasən zərflik vəzifəsində çıxış edir."}]$q$::jsonb from public.items where slug='zerf-komekci'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

insert into public.items (slug,kind,subject,title,subtitle,sort,price,question_count,minutes,mode) values ('sintaksis','topic','azerbaycan-dili','Söz birləşmələri və cümlə üzvləri','I, II, III növ birləşmələr; baş və ikinci dərəcəli üzvlər · 18 sual',10,2.0,18,0,'learn')
  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Cümlənin baş üzvləri hansılardır?", "o": ["Mübtəda və xəbər", "Təyin və tamamlıq", "Zərflik və təyin", "Yalnız xəbər"], "a": 0, "e": "Mübtəda və xəbər cümlənin qrammatik əsasını təşkil edir."}, {"s": "Cümlənin ikinci dərəcəli üzvləri hansılardır?", "o": ["Mübtəda, xəbər", "Tamamlıq, təyin, zərflik", "Yalnız təyin", "Qoşma, bağlayıcı"], "a": 1, "e": "İkinci dərəcəli üzvlər baş üzvləri izah edir."}, {"s": "Mübtəda hansı suallara cavab verir?", "o": ["Kim? Nə?", "Kimi? Nəyi?", "Necə?", "Harada?"], "a": 0, "e": "Mübtəda adlıq halda olur və «kim? nə?» sualına cavab verir."}, {"s": "«Uşaq kitabı oxudu» cümləsində «kitabı» hansı üzvdür?", "o": ["Mübtəda", "Vasitəsiz tamamlıq", "Vasitəli tamamlıq", "Təyin"], "a": 1, "e": "Təsirlik halda olub təsirli feilə aiddir — vasitəsiz tamamlıqdır."}, {"s": "Vasitəli tamamlıq hansı hallarda olur?", "o": ["Yalnız təsirlik halda", "Yönlük, yerlik, çıxışlıq hallarda", "Yalnız adlıq halda", "Heç bir halda"], "a": 1, "e": "Vasitəsiz tamamlıq təsirlik halda, vasitəli tamamlıq digər hallarda olur."}, {"s": "Təyin hansı suallara cavab verir?", "o": ["Necə? Nə cür? Hansı? Neçə?", "Kim? Nə?", "Nə zaman?", "Niyə?"], "a": 0, "e": "Təyin əşyanın əlamətini bildirir və ismə aid olur."}, {"s": "«Dünən məktəbə getdim» cümləsində «dünən» hansı üzvdür?", "o": ["Tamamlıq", "Təyin", "Zərflik", "Mübtəda"], "a": 2, "e": "Zaman zərfliyidir, «nə zaman?» sualına cavab verir."}, {"s": "Söz birləşmələri neçə yerə bölünür?", "o": ["İsmi və feili birləşmələr", "Sadə və mürəkkəb", "Tək və cəm", "Baş və ikinci dərəcəli"], "a": 0, "e": "Əsas tərəfinə görə ismi və feili söz birləşmələri fərqləndirilir."}, {"s": "Təyini söz birləşmələrinin neçə növü var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "I, II və III növ təyini söz birləşmələri."}, {"s": "«Dəmir qapı» hansı növ təyini söz birləşməsidir?", "o": ["I növ", "II növ", "III növ", "Feili birləşmə"], "a": 0, "e": "Hər iki tərəf şəkilçisizdir — I növ."}, {"s": "«Qapı dəstəyi» hansı növ təyini söz birləşməsidir?", "o": ["I növ", "II növ", "III növ", "Feili birləşmə"], "a": 1, "e": "Birinci tərəf şəkilçisiz, ikinci tərəf mənsubiyyət şəkilçilidir — II növ."}, {"s": "«Qapının dəstəyi» hansı növ təyini söz birləşməsidir?", "o": ["I növ", "II növ", "III növ", "Qoşmalı birləşmə"], "a": 2, "e": "Birinci tərəf yiyəlik halda, ikinci tərəf mənsubiyyət şəkilçilidir — III növ."}, {"s": "Xəbər cümlədə nəyi bildirir?", "o": ["Əşyanın adını", "Mübtəda haqqında məlumatı", "Əşyanın əlamətini", "Hərəkətin yerini"], "a": 1, "e": "Xəbər mübtədanın nə etdiyini və ya nə olduğunu bildirir."}, {"s": "Cümlənin qrammatik əsası nədir?", "o": ["Mübtəda və xəbər", "Təyin və tamamlıq", "Yalnız mübtəda", "Zərflik"], "a": 0, "e": "Baş üzvlərin birliyi cümlənin qrammatik əsasını təşkil edir."}, {"s": "«Gözəl mənzərə» birləşməsində «gözəl» hansı üzvdür?", "o": ["Mübtəda", "Xəbər", "Təyin", "Zərflik"], "a": 2, "e": "İsmin əlamətini bildirir — təyindir."}, {"s": "Həmcins üzvlər nədir?", "o": ["Eyni suala cavab verən, eyni üzvə aid olan sözlər", "Yalnız mübtədalar", "Yalnız xəbərlər", "Köməkçi sözlər"], "a": 0, "e": "Həmcins üzvlər arasında vergül qoyulur və ya «və» bağlayıcısı işlənir."}, {"s": "«Dostuma məktub yazdım» cümləsində «dostuma» hansı üzvdür?", "o": ["Vasitəsiz tamamlıq", "Vasitəli tamamlıq", "Təyin", "Mübtəda"], "a": 1, "e": "Yönlük haldadır — vasitəli tamamlıqdır."}, {"s": "Mübtədası olmayan, lakin xəbəri olan cümlələr necə adlanır?", "o": ["Cüttərkibli", "Təktərkibli", "Yarımçıq", "Mürəkkəb"], "a": 1, "e": "Təktərkibli cümlələrdə baş üzvlərdən yalnız biri iştirak edir."}]$q$::jsonb from public.items where slug='sintaksis'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

