insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Cümlələr məqsəd və intonasiyaya görə neçə yerə bölünür?", "o": ["2", "3", "4", "5"], "a": 2, "e": "Nəqli, sual, əmr və nida cümlələri."}, {"s": "«Sabah gələcəyəm.» Bu cümlə məqsədinə görə necədir?", "o": ["Nəqli", "Sual", "Əmr", "Nida"], "a": 0, "e": "Məlumat verir, sonunda nöqtə qoyulur."}, {"s": "«Nə vaxt gəlirsən?» Bu cümlə məqsədinə görə necədir?", "o": ["Nəqli", "Sual", "Əmr", "Nida"], "a": 1, "e": "Sual bildirir, sonunda sual işarəsi qoyulur."}, {"s": "Cümlələr quruluşuna görə neçə yerə bölünür?", "o": ["Sadə və mürəkkəb", "Nəqli və sual", "Tək və cəm", "Baş və budaq"], "a": 0, "e": "Bir qrammatik əsası olan cümlə sadə, iki və daha çox əsası olan cümlə mürəkkəbdir."}, {"s": "Mürəkkəb cümlələr neçə yerə bölünür?", "o": ["Tabesiz və tabeli", "Nəqli və sual", "Sadə və düzəltmə", "Tam və yarımçıq"], "a": 0, "e": "Tabesiz mürəkkəb cümlədə hissələr bərabərhüquqlu, tabeli mürəkkəb cümlədə biri digərindən asılıdır."}, {"s": "Tabeli mürəkkəb cümlənin hissələri necə adlanır?", "o": ["Mübtəda və xəbər", "Baş və budaq cümlə", "Birinci və ikinci cümlə", "Sadə və mürəkkəb"], "a": 1, "e": "Budaq cümlə baş cümləni izah edir."}, {"s": "Həmcins üzvlər arasında hansı durğu işarəsi qoyulur?", "o": ["Nöqtə", "Vergül", "İki nöqtə", "Sual işarəsi"], "a": 1, "e": "«Və» bağlayıcısı olmadıqda həmcins üzvlər arasında vergül qoyulur."}, {"s": "Xitabdan sonra hansı durğu işarəsi qoyulur?", "o": ["Nöqtə", "Vergül", "Defis", "Mötərizə"], "a": 1, "e": "«Ay bala, bura gəl.» — xitab vergüllə ayrılır."}, {"s": "Ümumiləşdirici sözdən sonra gələn həmcins üzvlərdən əvvəl hansı işarə qoyulur?", "o": ["Vergül", "İki nöqtə", "Nöqtəli vergül", "Tire"], "a": 1, "e": "«Bağda müxtəlif ağaclar var: alma, armud, heyva.»"}, {"s": "Mübtəda ilə xəbər arasında isim və ya əvəzliklə ifadə olunduqda hansı işarə qoyulur?", "o": ["Vergül", "Tire", "İki nöqtə", "Heç nə"], "a": 1, "e": "«Bakı — Azərbaycanın paytaxtıdır.»"}, {"s": "«Mən bilirəm ki, sən gələcəksən» cümləsi necə cümlədir?", "o": ["Sadə", "Tabesiz mürəkkəb", "Tabeli mürəkkəb", "Yarımçıq"], "a": 2, "e": "«Ki» tabelilik bağlayıcısıdır, ikinci hissə budaq cümlədir."}, {"s": "«Külək əsdi, yarpaqlar töküldü» cümləsi necə cümlədir?", "o": ["Sadə", "Tabesiz mürəkkəb", "Tabeli mürəkkəb", "Təktərkibli"], "a": 1, "e": "İki bərabərhüquqlu sadə cümlə vergüllə bağlanıb."}, {"s": "Nida cümləsinin sonunda hansı işarə qoyulur?", "o": ["Nöqtə", "Sual işarəsi", "Nida işarəsi", "Çox nöqtə"], "a": 2, "e": "Güclü hiss bildirən cümlənin sonunda nida işarəsi qoyulur."}, {"s": "Cümlənin baş üzvlərinin hər ikisi iştirak edirsə, cümlə necə adlanır?", "o": ["Təktərkibli", "Cüttərkibli", "Yarımçıq", "Mürəkkəb"], "a": 1, "e": "Həm mübtəda, həm xəbər varsa — cüttərkibli cümlədir."}, {"s": "Sadə cümlədə neçə qrammatik əsas olur?", "o": ["1", "2", "3", "Qeyri-müəyyən"], "a": 0, "e": "Sadə cümlənin bir qrammatik əsası (mübtəda + xəbər) olur."}, {"s": "Müraciət bildirən söz necə adlanır?", "o": ["Xitab", "Ara söz", "Təyin", "Tamamlıq"], "a": 0, "e": "Xitab cümlə üzvü olmur və vergüllə ayrılır."}, {"s": "Ara sözlər cümlədə necə ayrılır?", "o": ["Vergüllə", "Tire ilə", "Ayrılmır", "Dırnaqla"], "a": 0, "e": "«Məncə, bu fikir düzgündür.» — ara söz vergüllə ayrılır."}, {"s": "«Çünki» bağlayıcısı hansı budaq cümləni bağlayır?", "o": ["Zaman", "Səbəb", "Şərt", "Məqsəd"], "a": 1, "e": "«Çünki» səbəb budaq cümləsini baş cümləyə bağlayır."}]$q$::jsonb from public.items where slug='cumle-durgu'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

