insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Hansı söz düzgün yazılıb?", "o": ["müəllim", "muəllim", "müəllım", "mühəllim"], "a": 0, "e": "Düzgün forma: müəllim."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["ailə", "ayilə", "aylə", "aielə"], "a": 0, "e": "Düzgün forma: ailə."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["tələbbə", "tələbə", "tələbə́", "teləbə"], "a": 1, "e": "Düzgün forma: tələbə."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["sahibkar", "saibkar", "sahipkar", "sahibqar"], "a": 0, "e": "Düzgün forma: sahibkar."}, {"s": "Hansı sözdə qoşa samit düzgün yazılıb?", "o": ["hiss", "his", "hizz", "hıs"], "a": 0, "e": "«Hiss» sözü qoşa «s» ilə yazılır."}, {"s": "Xüsusi isimlər necə yazılır?", "o": ["Kiçik hərflə", "Böyük hərflə", "Dırnaq içində", "Defislə"], "a": 1, "e": "Şəxs, yer, əsər adları böyük hərflə yazılır."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["məsələ", "məsəllə", "məsala", "mesələ"], "a": 0, "e": "Düzgün forma: məsələ."}, {"s": "Sıra sayları rəqəmlə yazıldıqda necə göstərilir?", "o": ["5ci", "5-ci", "5 ci", "5'ci"], "a": 1, "e": "Şəkilçi defislə birləşdirilir: 5-ci, 10-cu."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["əlbətdə", "əlbəttə", "albəttə", "əlbətte"], "a": 1, "e": "Düzgün forma: əlbəttə — qoşa «t» ilə."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["ixtisas", "ixdisas", "ictisas", "ihtisas"], "a": 0, "e": "Düzgün forma: ixtisas."}, {"s": "Hansı cərgədə sözlər düzgün yazılıb?", "o": ["qayda, layihə, məsuliyyət", "qaydə, layıhə, məsulyyət", "qayda, layıhə, məsuliyət", "qaydə, layihə, məsuliyyət"], "a": 0, "e": "Düzgün formalar: qayda, layihə, məsuliyyət."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["mütəxəssis", "mütəxəsis", "mutəxəssis", "mütaxəssis"], "a": 0, "e": "Düzgün forma: mütəxəssis — qoşa «s» ilə."}, {"s": "Mürəkkəb sözlər necə yazıla bilər?", "o": ["Yalnız bitişik", "Yalnız defislə", "Bitişik və ya defislə", "Yalnız ayrı"], "a": 2, "e": "Bəzi mürəkkəb sözlər bitişik (günəbaxan), bəziləri defislə (bir-bir) yazılır."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["iştirak", "işdirak", "iştırak", "iştirrak"], "a": 0, "e": "Düzgün forma: iştirak."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["fəaliyyət", "faaliyyət", "fəalyyət", "fəaliyət"], "a": 0, "e": "Düzgün forma: fəaliyyət."}, {"s": "Qoşa yazılan sözlər arasında nə qoyulur?", "o": ["Vergül", "Defis", "Nöqtə", "Heç nə"], "a": 1, "e": "«Bir-bir», «tez-tez», «ağ-qara» — defislə yazılır."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["təşəkkür", "təşəkür", "teşəkkür", "təşakkür"], "a": 0, "e": "Düzgün forma: təşəkkür — qoşa «k» ilə."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["cəmiyyət", "cəmiyət", "camiyyət", "cəmmiyyət"], "a": 0, "e": "Düzgün forma: cəmiyyət."}]$q$::jsonb from public.items where slug='orfoqrafiya'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

insert into public.items (slug,kind,subject,title,subtitle,sort,price,question_count,minutes,mode) values ('burax-1','exam','azerbaycan-dili','Buraxılış · Variant 1','Bütün bölmələri əhatə edən tam variant',101,3.0,20,25,'exam')
  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "«Qaranquş» sözü quruluşuna görə necədir?", "o": ["Sadə", "Düzəltmə", "Mürəkkəb", "Qoşa"], "a": 2, "e": "qara + quş — iki kökün birləşməsindən yaranıb."}, {"s": "Hansı sözdə sait düşümü baş verir?", "o": ["kitab — kitabı", "sinif — sinfi", "ev — evi", "qapı — qapısı"], "a": 1, "e": "sinif → sinfi. İkinci hecanın saiti düşür."}, {"s": "«Yaşıl ot» birləşməsi hansı növ təyini söz birləşməsidir?", "o": ["I növ", "II növ", "III növ", "Feili birləşmə"], "a": 0, "e": "Hər iki tərəf şəkilçisizdir."}, {"s": "«Mən sənə kitab verdim» cümləsində «sənə» hansı üzvdür?", "o": ["Mübtəda", "Vasitəsiz tamamlıq", "Vasitəli tamamlıq", "Təyin"], "a": 2, "e": "Yönlük haldadır — vasitəli tamamlıqdır."}, {"s": "«Oxunmuşdu» feilində neçə şəkilçi var?", "o": ["1", "2", "3", "4"], "a": 2, "e": "oxu + n (məchul) + muş (nəqli keçmiş) + du — növ, zaman və hekayə şəkilçiləri."}, {"s": "Hansı söz zərfdir?", "o": ["uca", "ucadan", "ucalıq", "ucalmaq"], "a": 1, "e": "«Ucadan» tərzi-hərəkət zərfidir — «necə?» sualına cavab verir."}, {"s": "Hansı cərgədə antonimlər verilib?", "o": ["sevinc — fərəh", "cəsarətli — qorxmaz", "işıqlı — qaranlıq", "böyük — iri"], "a": 2, "e": "«İşıqlı» və «qaranlıq» əks mənalıdır."}, {"s": "«Əlbəttə, o gələcək» cümləsində «əlbəttə» nədir?", "o": ["Xitab", "Ara söz (modal söz)", "Təyin", "Zərflik"], "a": 1, "e": "Danışanın fikrə münasibətini bildirir, vergüllə ayrılır."}, {"s": "Hansı feil icbar növdədir?", "o": ["yazıldı", "yazışdı", "yazdırdı", "yazınırdı"], "a": 2, "e": "«-dır» şəkilçisi işin başqasına gördürüldüyünü bildirir."}, {"s": "«Beşinci» sözü hansı say növüdür?", "o": ["Miqdar", "Sıra", "Kəsr", "Qeyri-müəyyən"], "a": 1, "e": "«-inci» sıra sayı şəkilçisidir."}, {"s": "Hansı söz ahəng qanununa tabedir?", "o": ["kitab", "qələm", "gəlirlər", "ilan"], "a": 2, "e": "«Gəlirlər» sözündə bütün saitlər incədir."}, {"s": "«Dostum, bura gəl!» cümləsində «dostum» nədir?", "o": ["Mübtəda", "Xitab", "Tamamlıq", "Təyin"], "a": 1, "e": "Müraciət bildirir, cümlə üzvü deyil, vergüllə ayrılır."}, {"s": "Hansı söz mücərrəd isimdir?", "o": ["ağac", "daş", "ümid", "pəncərə"], "a": 2, "e": "«Ümid» duyğu üzvləri ilə qavranılmır."}, {"s": "«Gələrkən» sözü feilin hansı formasıdır?", "o": ["Məsdər", "Feili sifət", "Feili bağlama", "Əmr"], "a": 2, "e": "«-arkən, -ərkən» feili bağlama şəkilçisidir."}, {"s": "Cümlə: «Hava soyuqdur.» Xəbər hansı nitq hissəsi ilə ifadə olunub?", "o": ["İsim", "Sifət", "Feil", "Zərf"], "a": 1, "e": "«Soyuqdur» sifətə xəbərlik şəkilçisi artırılmaqla düzəlib."}, {"s": "Hansı sözdə «k» səsi «y»-yə çevrilir?", "o": ["kitab — kitabı", "çiçək — çiçəyi", "qapı — qapını", "ev — evi"], "a": 1, "e": "çiçək → çiçəyi. Söz sonundakı «k» saitlə başlayan şəkilçi qarşısında «y» olur."}, {"s": "«Çox gözəl mənzərə» ifadəsində «çox» hansı nitq hissəsidir?", "o": ["Say", "Zərf", "Sifət", "Əvəzlik"], "a": 1, "e": "Sifətin əlamətini gücləndirir — miqdar zərfidir."}, {"s": "Hansı cümlə tabesiz mürəkkəb cümlədir?", "o": ["Bilirəm ki, gələcəksən.", "Yağış yağdı, hava sərinlədi.", "Gələn adam müəllimdir.", "Kitabı oxudum."], "a": 1, "e": "İki bərabərhüquqlu sadə cümlə vergüllə bağlanıb."}, {"s": "«Uşaqlarımızdan» sözündə neçə şəkilçi var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "uşaq + lar + ımız + dan — 3 şəkilçi."}, {"s": "Hansı söz omonimdir?", "o": ["kitab", "yaz", "qapı", "müəllim"], "a": 1, "e": "«Yaz» — həm fəsil adı, həm «yazmaq» feilinin əmr formasıdır."}]$q$::jsonb from public.items where slug='burax-1'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

