  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Azərbaycan dilində neçə dodaqlanan sait var?", "o": ["2", "3", "4", "5"], "a": 2, "e": "o, u, ö, ü — 4 dodaqlanan sait."}, {"s": "«Gözlük» sözü quruluşuna görə necədir?", "o": ["Sadə", "Düzəltmə", "Mürəkkəb", "Qoşa"], "a": 1, "e": "göz + lük — kök və leksik şəkilçi."}, {"s": "«Şəhərin küçələri» birləşməsi hansı növdür?", "o": ["I növ", "II növ", "III növ", "Feili birləşmə"], "a": 2, "e": "Birinci tərəf yiyəlik halda, ikinci tərəf mənsubiyyət şəkilçilidir."}, {"s": "Hansı feil məchul növdədir?", "o": ["yazdı", "yazıldı", "yazdırdı", "yazışdı"], "a": 1, "e": "«-ıl» məchul növ şəkilçisidir, iş görən bəlli deyil."}, {"s": "«Mənim kitabım» birləşməsində «mənim» hansı haldadır?", "o": ["Adlıq", "Yiyəlik", "Yönlük", "Təsirlik"], "a": 1, "e": "«Kimin?» sualına cavab verir."}, {"s": "Hansı söz təsirsiz feildir?", "o": ["oxumaq", "yazmaq", "yatmaq", "görmək"], "a": 2, "e": "«Yatmaq» vasitəsiz tamamlıq tələb etmir."}, {"s": "«Tez-tez» sözü necə yazılır?", "o": ["Bitişik", "Defislə", "Ayrı", "Dırnaqda"], "a": 1, "e": "Qoşa sözlər defislə yazılır."}, {"s": "Hansı cərgədə yalnız köməkçi nitq hissələri var?", "o": ["və, üçün, ki", "gözəl, uca, dərin", "mən, sən, o", "gəl, get, bax"], "a": 0, "e": "«və» bağlayıcı, «üçün» qoşma, «ki» bağlayıcı/ədatdır."}, {"s": "«Sarı yarpaqlar yerə töküldü» cümləsində neçə söz ikinci dərəcəli üzvdür?", "o": ["1", "2", "3", "4"], "a": 1, "e": "«Sarı» (təyin) və «yerə» (vasitəli tamamlıq) — 2 ikinci dərəcəli üzv."}, {"s": "«Oxumalıdır» feili hansı şəkildədir?", "o": ["Xəbər", "Vacib", "Lazım", "Arzu"], "a": 1, "e": "«-malı» vacib şəklinin şəkilçisidir."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["mütəxəsis", "mütəxəssis", "mütaxəssis", "mutəxəssis"], "a": 1, "e": "Düzgün forma: mütəxəssis."}, {"s": "«Dəniz kənarı» birləşməsi hansı növdür?", "o": ["I növ", "II növ", "III növ", "Qoşmalı"], "a": 1, "e": "Birinci tərəf şəkilçisiz, ikinci tərəf mənsubiyyət şəkilçilidir."}, {"s": "Hansı sözdə mənsubiyyət şəkilçisi var?", "o": ["evlər", "evdən", "eviniz", "evdə"], "a": 2, "e": "«-iniz» II şəxs cəmin mənsubiyyət şəkilçisidir."}, {"s": "«Ah, nə gözəl mənzərədir!» cümləsində «ah» nədir?", "o": ["Ədat", "Nida", "Modal söz", "Qoşma"], "a": 1, "e": "Hiss və həyəcan bildirir — nidadır."}, {"s": "Cümlə: «Kitab oxumaq xoşuma gəlir.» «Oxumaq» hansı formadır?", "o": ["Feili sifət", "Feili bağlama", "Məsdər", "Əmr"], "a": 2, "e": "«-maq» məsdər şəkilçisidir."}, {"s": "Hansı söz sifətin çoxaltma dərəcəsindədir?", "o": ["ağımtıl", "ağ", "ağappaq", "ağlıq"], "a": 2, "e": "İlk hecanın təkrarı ilə yaranan çoxaltma dərəcəsidir."}, {"s": "«Çünki» hansı bağlayıcıdır?", "o": ["Tabesizlik", "Tabelilik", "Qoşma", "Ədat"], "a": 1, "e": "Səbəb budaq cümləsini baş cümləyə bağlayır."}, {"s": "«Beşdə üç» ifadəsi hansı saydır?", "o": ["Miqdar", "Sıra", "Kəsr", "Qeyri-müəyyən"], "a": 2, "e": "Hissə bildirir — kəsr sayıdır."}, {"s": "Hansı cümlə təktərkiblidir?", "o": ["Uşaq gəldi.", "Axşam düşdü.", "Darıxdım.", "Hava gözəldir."], "a": 2, "e": "«Darıxdım» cümləsində mübtəda yoxdur, yalnız xəbər var."}, {"s": "Hansı söz arxaizmdir?", "o": ["kompüter", "sərkərdə", "telefon", "məktəb"], "a": 1, "e": "«Sərkərdə» köhnəlmiş sözdür, müasir dildə az işlənir."}]$q$::jsonb from public.items where slug='burax-2'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

