  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "«Müəllimlərimizə» sözündə şəkilçilərin düzgün ardıcıllığı hansıdır?", "o": ["Hal, cəm, mənsubiyyət", "Cəm, mənsubiyyət, hal", "Mənsubiyyət, cəm, hal", "Cəm, hal, mənsubiyyət"], "a": 1, "e": "müəllim + lər + imiz + ə."}, {"s": "Hansı söz düzəltmə zərfdir?", "o": ["dünən", "sürətlə", "indi", "burada"], "a": 1, "e": "sürət + -lə — düzəltmə zərfdir."}, {"s": "«Qızıl üzük» birləşməsində «qızıl» hansı sifətdir?", "o": ["Əsli", "Nisbi", "Qoşa", "Mürəkkəb"], "a": 1, "e": "Materialı bildirir, dərəcə üzrə dəyişmir — nisbi sifətdir."}, {"s": "Hansı cümlədə tire işlənməlidir?", "o": ["Bakı Azərbaycanın paytaxtıdır", "Mən gəldim", "O oxuyur", "Hava soyuqdur"], "a": 0, "e": "Mübtəda və xəbər isimlə ifadə olunduqda aralarında tire qoyulur."}, {"s": "«Görüşmək» feili hansı növdədir?", "o": ["Məlum", "Məchul", "Qarşılıq-birgəlik", "İcbar"], "a": 2, "e": "«-üş» şəkilçisi qarşılıqlı hərəkət bildirir."}, {"s": "Hansı sözdə samit artımı baş verir?", "o": ["ata — atası", "kitab — kitabı", "ev — evi", "dost — dostu"], "a": 0, "e": "Saitlə bitən sözə saitlə başlayan şəkilçi artırılarkən «s» bitişdiricisi gəlir."}, {"s": "«Nə qədər çalışsan, o qədər irəli gedərsən» cümləsi necədir?", "o": ["Sadə", "Tabesiz mürəkkəb", "Tabeli mürəkkəb", "Yarımçıq"], "a": 2, "e": "Birinci hissə budaq, ikinci hissə baş cümlədir."}, {"s": "Hansı söz frazeoloji birləşmədir?", "o": ["uca dağ", "göz yummaq", "yaşıl ot", "böyük ev"], "a": 1, "e": "«Göz yummaq» = görməzdən gəlmək. Məcazi, sabit birləşmədir."}, {"s": "«Hamı» sözü hansı əvəzlikdir?", "o": ["Şəxs", "İşarə", "Təyini", "Sual"], "a": 2, "e": "Ümumilik bildirir — təyini əvəzlikdir."}, {"s": "Hansı sözdə qoşa samit var?", "o": ["dost", "üst", "əlbəttə", "kitab"], "a": 2, "e": "«Əlbəttə» qoşa «t» ilə yazılır."}, {"s": "«Yaşadığımız şəhər» birləşməsində «yaşadığımız» hansı formadır?", "o": ["Məsdər", "Feili sifət", "Feili bağlama", "Zərf"], "a": 1, "e": "İsmi təyin edir, feil əlaməti saxlayır — feili sifətdir."}, {"s": "Hansı cərgədə sözlər düzgün yazılıb?", "o": ["ixtisas, iştirak, fəaliyyət", "ihtisas, işdirak, faaliyyət", "ixdisas, iştirak, fəalyyət", "ixtisas, iştırak, fəaliyət"], "a": 0, "e": "Düzgün formalar: ixtisas, iştirak, fəaliyyət."}, {"s": "«Səhərdən bəri» ifadəsində «bəri» nədir?", "o": ["Zərf", "Qoşma", "Bağlayıcı", "Ədat"], "a": 1, "e": "Çıxışlıq hallı sözlə işlənən qoşmadır."}, {"s": "Hansı cümlədə həmcins üzvlər var?", "o": ["Uşaq gəldi.", "Alma, armud və heyva aldım.", "Hava soyuqdur.", "Mən oxuyuram."], "a": 1, "e": "«Alma, armud, heyva» — həmcins tamamlıqlar."}, {"s": "«İşıq» sözü ahəng qanununa tabedirmi?", "o": ["Bəli, bütün saitlər incədir", "Bəli, bütün saitlər qalındır", "Xeyr, həm incə, həm qalın sait var", "Sözdə bir sait var"], "a": 2, "e": "«i» incə, «ı» qalın saitdir — ahəng qanunu pozulub."}, {"s": "Hansı feil əmr şəklindədir?", "o": ["gəlir", "gələcək", "gəl", "gəlsə"], "a": 2, "e": "Əmr şəkli şəkilçisizdir (II şəxs tək)."}, {"s": "«Qapını açdı» cümləsində «qapını» hansı haldadır?", "o": ["Yiyəlik", "Təsirlik", "Yönlük", "Yerlik"], "a": 1, "e": "«Nəyi?» sualına cavab verir — müəyyən təsirlik haldır."}, {"s": "Hansı söz neologizmdir?", "o": ["sərkərdə", "ərəbxana", "internet", "xan"], "a": 2, "e": "«İnternet» dilə yeni daxil olmuş sözdür."}, {"s": "Cümlə: «Məncə, bu düzgün qərardır.» «Məncə» nədir?", "o": ["Xitab", "Ara söz", "Təyin", "Mübtəda"], "a": 1, "e": "Danışanın münasibətini bildirən ara sözdür, vergüllə ayrılır."}, {"s": "Hansı sözdə cingiltili samit karlaşır?", "o": ["kitab", "qapı", "ana", "ev"], "a": 0, "e": "«Kitab» sözünün sonundakı «b» [p] kimi tələffüz olunur."}]$q$::jsonb from public.items where slug='burax-3'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

