insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "«Dəmirçixana» sözü neçə morfemdən ibarətdir?", "o": ["2", "3", "4", "5"], "a": 1, "e": "dəmir + çi + xana — kök və iki leksik şəkilçi."}, {"s": "Hansı cərgədə bütün sözlər eyni nitq hissəsinə aiddir?", "o": ["gözəllik, dostluq, uşaqlıq", "gözəl, dostluq, oxumaq", "tez, gözəl, kitab", "gəl, uca, ev"], "a": 0, "e": "Hər üçü «-lıq» şəkilçisi ilə düzəlmiş mücərrəd isimdir."}, {"s": "«Oxunmalı kitab» birləşməsində «oxunmalı» hansı formadır?", "o": ["Məsdər", "Feili sifət", "Feili bağlama", "Vacib şəkli"], "a": 1, "e": "İsmi təyin edir — feili sifətdir. Vacib şəkli xəbər vəzifəsində olur."}, {"s": "Hansı cümlədə mübtəda feili sifətlə ifadə olunub?", "o": ["Gələn qaldı.", "Uşaq gəldi.", "Hava soyuqdur.", "Kitabı oxudum."], "a": 0, "e": "«Gələn» feili sifəti isimləşərək mübtəda olub."}, {"s": "«Beş-altı adam» ifadəsində say hansı növdədir?", "o": ["Müəyyən miqdar", "Qeyri-müəyyən miqdar", "Sıra", "Kəsr"], "a": 1, "e": "Qoşa saylar təqribi miqdar bildirir — qeyri-müəyyəndir."}, {"s": "Hansı feildə həm növ, həm zaman şəkilçisi var?", "o": ["gəldi", "yazılır", "oxu", "getsə"], "a": 1, "e": "yaz + ıl (məchul növ) + ır (indiki zaman)."}, {"s": "«Nə vaxt ki dərs bitdi, hamı getdi» cümləsində budaq cümlə hansıdır?", "o": ["Hamı getdi", "Nə vaxt ki dərs bitdi", "Hər ikisi", "Budaq cümlə yoxdur"], "a": 1, "e": "Zaman budaq cümləsidir, baş cümləni izah edir."}, {"s": "Hansı söz həm isim, həm feil kimi işlənə bilər?", "o": ["gözəl", "boya", "dərin", "tez"], "a": 1, "e": "«Boya» — rəng maddəsi (isim) və «boyamaq» feilinin kökü."}, {"s": "«Yazıçının əsəri» birləşməsində hansı qrammatik əlaqə var?", "o": ["Yanaşma", "Uzlaşma", "İdarə", "Əlaqə yoxdur"], "a": 1, "e": "III növ təyini söz birləşməsində tərəflər uzlaşma əlaqəsindədir."}, {"s": "Hansı sözdə həm sait düşümü, həm samit dəyişməsi baş verir?", "o": ["ağız — ağzı", "çörək — çörəyi", "oğul — oğlu", "kitab — kitabı"], "a": 0, "e": "ağız → ağzı: sait düşür. «ğ» qalır, lakin heca quruluşu dəyişir."}, {"s": "«Bu kitab mənimdir» cümləsində «mənimdir» hansı üzvdür?", "o": ["Mübtəda", "Xəbər", "Təyin", "Tamamlıq"], "a": 1, "e": "Əvəzliyə xəbərlik şəkilçisi artırılıb — ismi xəbərdir."}, {"s": "Hansı cərgədə omonimlər var?", "o": ["üz — sifət / üz — üzmək", "gözəl — qəşəng", "isti — soyuq", "ev — mənzil"], "a": 0, "e": "Yazılışı eyni, mənası tamamilə fərqli sözlərdir."}, {"s": "«Gəlib getdi» ifadəsində «gəlib» hansı formadır?", "o": ["Feili sifət", "Feili bağlama", "Məsdər", "Əmr"], "a": 1, "e": "«-ıb» feili bağlama şəkilçisidir, ikinci feilə tabedir."}, {"s": "Hansı cümlədə zərflik var?", "o": ["Kitabı oxudum.", "Səhər tezdən qalxdım.", "Gözəl mənzərədir.", "O, tələbədir."], "a": 1, "e": "«Səhər tezdən» zaman zərfliyidir."}, {"s": "«Qaçaraq gəldi» ifadəsində «qaçaraq» nəyi bildirir?", "o": ["Zamanı", "Tərzi", "Səbəbi", "Yeri"], "a": 1, "e": "«-araq» feili bağlaması hərəkətin tərzini bildirir."}, {"s": "Hansı söz birləşməsi feili birləşmədir?", "o": ["dəmir qapı", "kitab oxumaq", "qapının dəstəyi", "gözəl mənzərə"], "a": 1, "e": "Əsas tərəf feildir — feili birləşmədir."}, {"s": "«Nə qədər çox oxusan, bir o qədər çox bilərsən» cümləsində budaq cümlənin növü nədir?", "o": ["Zaman", "Dərəcə (kəmiyyət)", "Səbəb", "Şərt"], "a": 1, "e": "Hərəkətin dərəcəsini bildirən budaq cümlədir."}, {"s": "Hansı sözdə leksik və qrammatik şəkilçi birlikdə işlənib?", "o": ["kitablar", "dostluqda", "evdən", "qapını"], "a": 1, "e": "dost + luq (leksik) + da (qrammatik — hal şəkilçisi)."}, {"s": "«Ən yaxşı» ifadəsindəki dərəcə necə yaranıb?", "o": ["Şəkilçi ilə", "Söz vasitəsilə (analitik)", "Təkrarla", "Səs dəyişməsi ilə"], "a": 1, "e": "«Ən» sözü ilə yaranan analitik çoxaltma dərəcəsidir."}, {"s": "Hansı cümlə cüttərkibli sadə cümlədir?", "o": ["Qaranlıq düşdü.", "Darıxıram.", "Səhərdir.", "Yağış yağır, külək əsir."], "a": 0, "e": "Mübtəda (qaranlıq) və xəbər (düşdü) var, bir qrammatik əsas."}]$q$::jsonb from public.items where slug='qebul-1'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

insert into public.items (slug,kind,subject,title,subtitle,sort,price,question_count,minutes,mode) values ('qebul-2','exam','azerbaycan-dili','Qəbul · Variant 2','Mürəkkəb morfoloji təhlil və söz birləşmələri',105,3.0,20,30,'exam')
  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Hansı sözdə şəkilçi sözün mənasını dəyişib?", "o": ["kitablar", "evdə", "işçi", "qapını"], "a": 2, "e": "iş → işçi: yeni söz yaranıb, deməli leksik şəkilçidir."}, {"s": "«Yazılası məktub» ifadəsində «yazılası» hansı formadır?", "o": ["Lazım şəkli", "Feili sifət", "Məsdər", "Feili bağlama"], "a": 1, "e": "«-ası» şəkilçili forma ismi təyin edəndə feili sifətdir."}, {"s": "Hansı cərgədə hər iki söz çoxmənalıdır?", "o": ["baş, ayaq", "kitab, dəftər", "beş, on", "və, amma"], "a": 0, "e": "«Baş» (bədən üzvü, rəhbər, başlanğıc), «ayaq» (bədən üzvü, stolun ayağı, son)."}, {"s": "«Məktəbin həyətində» ifadəsində neçə şəkilçi var?", "o": ["2", "3", "4", "5"], "a": 2, "e": "məktəb + in (yiyəlik) + həyət + i (mənsubiyyət) + ndə (yerlik) — birləşmədə 3 şəkilçi."}, {"s": "Hansı cümlədə xəbər saylə ifadə olunub?", "o": ["Onlar beşdir.", "Beş kitab aldım.", "Beşinci sinifdəyəm.", "Beş-altı adam gəldi."], "a": 0, "e": "«Beşdir» — saya xəbərlik şəkilçisi artırılıb."}, {"s": "«Oxuduqca» sözündə hansı şəkilçi var?", "o": ["Feili sifət", "Feili bağlama", "Məsdər", "Zaman"], "a": 1, "e": "«-dıqca» feili bağlama şəkilçisidir, tədricilik bildirir."}, {"s": "Hansı söz quruluşca mürəkkəb feildir?", "o": ["gəlmək", "yazmaq", "kömək etmək", "oxumaq"], "a": 2, "e": "Ad + köməkçi feil birləşməsindən yaranan mürəkkəb feildir."}, {"s": "«O, kitabı mənə verdi» cümləsində neçə tamamlıq var?", "o": ["1", "2", "3", "Tamamlıq yoxdur"], "a": 1, "e": "«Kitabı» vasitəsiz, «mənə» vasitəli tamamlıqdır."}, {"s": "Hansı sözdə ahəng qanunu həm damaq, həm dodaq baxımından gözlənilir?", "o": ["gözlük", "kitablar", "qələmlər", "işıqlar"], "a": 0, "e": "göz-lük: hər iki sait incə və dodaqlanandır."}, {"s": "«Baxmayaraq» sözü hansı nitq hissəsi kimi işlənir?", "o": ["Feil", "Qoşma", "Bağlayıcı", "Nida"], "a": 1, "e": "«-a baxmayaraq» şəklində qoşma funksiyası daşıyır."}, {"s": "Hansı cümlədə təyin feili sifətlə ifadə olunub?", "o": ["Gözəl mənzərə açıldı.", "Oxunmuş kitab masadadır.", "Beş kitab aldım.", "Dəmir qapı bağlıdır."], "a": 1, "e": "«Oxunmuş» feili sifətdir və ismi təyin edir."}, {"s": "«Nə gəldi, nə də getdi» cümləsində hansı bağlayıcı var?", "o": ["Birləşdirmə", "İnkarlıq", "Qarşılaşdırma", "Bölüşdürmə"], "a": 1, "e": "«Nə... nə də» inkarlıq bağlayıcısıdır."}, {"s": "Hansı söz morfoloji yolla yaranıb?", "o": ["günəbaxan", "dəvəquşu", "dostluq", "boyunbağı"], "a": 2, "e": "Şəkilçi vasitəsilə yaranıb — morfoloji üsuldur. Digərləri sintaktik üsulla yaranıb."}, {"s": "«Səni görmək istəyirəm» cümləsində «görmək» hansı üzvdür?", "o": ["Mübtəda", "Vasitəsiz tamamlıq", "Xəbərin bir hissəsi", "Təyin"], "a": 1, "e": "«İstəyirəm» feilinin tamamlığıdır — nəyi istəyirəm? görmək."}, {"s": "Hansı cərgədə bütün sözlər təsirli feildir?", "o": ["oxumaq, yazmaq, görmək", "getmək, qaçmaq, yatmaq", "gülmək, ağlamaq, durmaq", "yatmaq, oturmaq, qalxmaq"], "a": 0, "e": "Hər üçü «kimi? nəyi?» sualına cavab verən tamamlıq tələb edir."}, {"s": "«Üzügülər» sözü necə yaranıb?", "o": ["Şəkilçi ilə", "İki kökün birləşməsi ilə", "Səs artımı ilə", "Təkrarla"], "a": 1, "e": "üz + ü + gülər — mürəkkəb sifətdir."}, {"s": "Hansı cümlədə mübtəda buraxılıb?", "o": ["Hava soyuqdur.", "Sabah gələcəyəm.", "Uşaq oynayır.", "Kitab maraqlıdır."], "a": 1, "e": "Şəxs şəkilçisi mübtədanı bildirir, ayrıca mübtəda yoxdur — təktərkiblidir."}, {"s": "«Bir az» ifadəsi hansı nitq hissəsidir?", "o": ["Say", "Zərf", "Sifət", "Əvəzlik"], "a": 1, "e": "Miqdar zərfidir — «nə qədər?» sualına cavab verir."}, {"s": "Hansı sözdə şəkilçi feildən sifət düzəldir?", "o": ["yazıçı", "gələn", "oxumaq", "yazı"], "a": 1, "e": "«-an, -ən» feildən feili sifət (sifət əlamətli forma) düzəldir."}, {"s": "«Qapı açıq idi» cümləsində «idi» nədir?", "o": ["Köməkçi feil (hekayə şəkilçisi)", "Əsas feil", "Qoşma", "Ədat"], "a": 0, "e": "«İdi» ismi xəbəri keçmiş zamana aid edən köməkçi vasitədir."}]$q$::jsonb from public.items where slug='qebul-2'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

