  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Hansı sözdə həm leksik, həm iki qrammatik şəkilçi var?", "o": ["kitablarda", "dostluqlarımız", "evdə", "qapılar"], "a": 1, "e": "dost + luq (leksik) + lar + ımız (qrammatik)."}, {"s": "«Oxumaq üçün gəldim» cümləsində «oxumaq üçün» nədir?", "o": ["Tamamlıq", "Məqsəd zərfliyi", "Təyin", "Mübtəda"], "a": 1, "e": "«Nə məqsədlə?» sualına cavab verir."}, {"s": "Hansı cümlədə tabesizlik bağlayıcısı var?", "o": ["Bilirəm ki, gələcək.", "Gəldim, amma onu tapmadım.", "Nə vaxt gəlsən, gözləyirəm.", "Çünki gecikdim."], "a": 1, "e": "«Amma» qarşılaşdırma bildirən tabesizlik bağlayıcısıdır."}, {"s": "«Gözəlliyi» sözündə neçə şəkilçi var?", "o": ["1", "2", "3", "4"], "a": 2, "e": "göz + əl + lik + i → gözəlliyi: iki leksik, bir mənsubiyyət/hal şəkilçisi."}, {"s": "Hansı söz birləşməsində uzlaşma əlaqəsi var?", "o": ["dəmir qapı", "qapının dəstəyi", "sürətlə qaçmaq", "evə getmək"], "a": 1, "e": "III növ təyini söz birləşməsində tərəflər şəxsə və kəmiyyətə görə uzlaşır."}, {"s": "«Dünən gələn qonaq bu gün getdi» cümləsində «gələn» hansı üzvdür?", "o": ["Xəbər", "Təyin", "Mübtəda", "Zərflik"], "a": 1, "e": "«Qonaq» isminin əlamətini bildirir — təyindir."}, {"s": "Hansı feil forması şəxsə görə dəyişmir?", "o": ["gəlirəm", "gəldin", "gəlmək", "gələcəyik"], "a": 2, "e": "Məsdər təsriflənməyən formadır."}, {"s": "«Kaş gələydi» cümləsində feil hansı şəkildədir?", "o": ["Əmr", "Arzu", "Şərt", "Vacib"], "a": 1, "e": "«Kaş» ədatı ilə işlənən arzu şəklidir."}, {"s": "Hansı cümlədə ara söz var?", "o": ["Yağış yağır.", "Deyəsən, yağış yağacaq.", "Yağış yağdı, hava sərinlədi.", "Yağışı sevirəm."], "a": 1, "e": "«Deyəsən» danışanın şübhəsini bildirən modal sözdür."}, {"s": "«Ağacın budağı sındı» cümləsində mübtəda hansıdır?", "o": ["ağacın", "budağı", "sındı", "ağacın budağı"], "a": 3, "e": "III növ təyini söz birləşməsi bütövlükdə mübtəda vəzifəsindədir."}, {"s": "Hansı söz quruluşuna görə digərlərindən fərqlənir?", "o": ["dostluq", "işçi", "gözlük", "dəvəquşu"], "a": 3, "e": "«Dəvəquşu» mürəkkəb, qalanları düzəltmə sözdür."}, {"s": "«Daha gözəl» ifadəsində dərəcə necə ifadə olunub?", "o": ["Şəkilçi ilə", "Söz vasitəsilə", "Təkrarla", "Dərəcə yoxdur"], "a": 1, "e": "Analitik yolla — «daha» sözü ilə çoxaltma dərəcəsi yaranıb."}, {"s": "Hansı cümlədə vasitəsiz tamamlıq var?", "o": ["Evə getdim.", "Məktubu yazdım.", "Dostumla danışdım.", "Şəhərdən gəldim."], "a": 1, "e": "«Məktubu» təsirlik haldadır və təsirli feilə aiddir."}, {"s": "«Yarpaqlar sarala-sarala töküldü» ifadəsində təkrar nəyi bildirir?", "o": ["Tərzi və davamiyyəti", "Zamanı", "Səbəbi", "Yeri"], "a": 0, "e": "Feili bağlamanın təkrarı hərəkətin tədricən davam etdiyini bildirir."}, {"s": "Hansı cərgədə sözlərin hamısı alınmadır?", "o": ["kompüter, telefon, universitet", "dağ, çay, meşə", "ev, qapı, pəncərə", "gəl, get, bax"], "a": 0, "e": "Üçü də başqa dillərdən alınmış sözlərdir."}, {"s": "«Gedə bilmirəm» ifadəsində «bilmirəm» nədir?", "o": ["Əsas feil", "Köməkçi feil", "Qoşma", "Ədat"], "a": 1, "e": "Bacarıq bildirən köməkçi feildir, əsas feil «getmək»dir."}, {"s": "Hansı cümlədə xəbər zərflə ifadə olunub?", "o": ["Hava soyuqdur.", "Toplantı sabahdır.", "O, müəllimdir.", "Kitab maraqlıdır."], "a": 1, "e": "«Sabah» zaman zərfi xəbərlik şəkilçisi qəbul edib."}, {"s": "«Nə üçün gəlmədin?» cümləsində «nə üçün» nədir?", "o": ["Sual əvəzliyi + qoşma", "Bağlayıcı", "Nida", "Modal söz"], "a": 0, "e": "Sual əvəzliyi «nə» ilə qoşma «üçün» birləşərək səbəb soruşur."}, {"s": "Hansı sözdə vurğu son hecaya düşmür?", "o": ["kitab", "müəllim", "dünən", "qələm"], "a": 2, "e": "Zərflərdə vurğu çox vaxt birinci hecaya düşür: dünən, indi, sabah."}, {"s": "«Oxuyub gəldi» ifadəsində iki feil arasında hansı əlaqə var?", "o": ["Tabesizlik", "Tabelilik (feili bağlama əsas feilə tabedir)", "Əlaqə yoxdur", "Uzlaşma"], "a": 1, "e": "Feili bağlama əsas feili izah edir, ona tabedir."}]$q$::jsonb from public.items where slug='qebul-3'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

insert into public.items (slug,kind,subject,title,subtitle,sort,price,question_count,minutes,mode) values ('qar-sehv','mixed','azerbaycan-dili','Səhv tapma testi','Orfoqrafiya, durğu işarəsi və uzlaşma səhvlərini tap',107,2.0,20,20,'exam')
  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Hansı sözdə orfoqrafik səhv var?", "o": ["müəllim", "təşəkkür", "mesələ", "ailə"], "a": 2, "e": "Düzgün forma: məsələ."}, {"s": "Hansı sözdə orfoqrafik səhv var?", "o": ["fəaliyyət", "iştirak", "ixdisas", "cəmiyyət"], "a": 2, "e": "Düzgün forma: ixtisas."}, {"s": "Hansı cümlədə durğu işarəsi səhv qoyulub?", "o": ["Dostum, bura gəl.", "Məncə bu düzdür.", "Alma, armud aldım.", "Bakı — paytaxtdır."], "a": 1, "e": "Ara söz «məncə»dən sonra vergül qoyulmalıdır."}, {"s": "Hansı birləşmə səhv qurulub?", "o": ["beş kitab", "beş kitablar", "beşinci kitab", "bir neçə kitab"], "a": 1, "e": "Saydan sonra isim cəm şəkilçisi qəbul etmir."}, {"s": "Hansı cümlədə şəxsə görə uzlaşma səhvdir?", "o": ["Mən gəldim.", "Sən gəldin.", "Mən gəldin.", "Biz gəldik."], "a": 2, "e": "«Mən» I şəxs təkdir, xəbər «gəldim» olmalıdır. «Gəldin» II şəxsin şəkilçisidir."}, {"s": "Hansı sözdə şəkilçi səhv artırılıb?", "o": ["kitabda", "evdən", "qapıya", "ataya-sı"], "a": 3, "e": "Düzgün forma: atası. Şəkilçi defislə ayrılmır."}, {"s": "Hansı sözdə ahəng qanunu pozulub?", "o": ["gözlük", "qapılar", "evdə", "kitabdan"], "a": 3, "e": "«Kitab» özü ahəng qanununa tabe deyil (i + a)."}, {"s": "Hansı cümlədə söz sırası pozulub?", "o": ["Mən məktəbə gedirəm.", "Gedirəm məktəbə mən.", "Dostum kitab oxuyur.", "Hava soyuqdur."], "a": 1, "e": "Azərbaycan dilində adi söz sırası: mübtəda — tamamlıq — xəbər."}, {"s": "Hansı sözdə qoşa samit səhvən yazılmayıb?", "o": ["əlbətə", "hiss", "təşəkkür", "mütəxəssis"], "a": 0, "e": "Düzgün forma: əlbəttə."}, {"s": "Hansı ifadə səhvdir?", "o": ["ən gözəl", "daha gözəl", "ən gözəlraq", "çox gözəl"], "a": 2, "e": "«Ən» və «-raq» eyni vaxtda işlənmir."}, {"s": "Hansı cümlədə tire səhv işlənib?", "o": ["Bakı — Azərbaycanın paytaxtıdır.", "Mən — gəldim.", "Nizami — böyük şairdir.", "Su — həyat mənbəyidir."], "a": 1, "e": "Xəbər feillə ifadə olunduqda tire qoyulmur."}, {"s": "Hansı sözdə hərf səhvi var?", "o": ["sahibkar", "mütaxəssis", "qayda", "layihə"], "a": 1, "e": "Düzgün forma: mütəxəssis."}, {"s": "Hansı cərgədə söz düzgün hecalara bölünüb?", "o": ["mü-əl-lim", "müəl-lim", "mü-əll-im", "müə-llim"], "a": 0, "e": "Hər hecada bir sait olmalıdır: mü-əl-lim."}, {"s": "Hansı cümlədə həmcins üzvlər arasında vergül çatışmır?", "o": ["Alma, armud aldım.", "Alma armud heyva aldım.", "Alma və armud aldım.", "Alma ilə armud aldım."], "a": 1, "e": "Bağlayıcısız həmcins üzvlər arasında vergül qoyulmalıdır."}, {"s": "Hansı söz səhv yazılıb?", "o": ["iştirak", "işdirak", "ixtisas", "fəaliyyət"], "a": 1, "e": "Düzgün forma: iştirak. Yazıda «t» saxlanılır."}, {"s": "Hansı sıra sayı düzgün yazılıb?", "o": ["5ci", "5-ci", "5 ci", "5.ci"], "a": 1, "e": "Rəqəmlə yazılan sıra sayına şəkilçi defislə birləşir."}, {"s": "Hansı cümlədə xitab vergüllə ayrılmayıb?", "o": ["Ana, mən gəldim.", "Dostum bura gəl.", "Müəllim, sual verim?", "Uşaqlar, sakit olun."], "a": 1, "e": "«Dostum» xitabdır, ondan sonra vergül qoyulmalıdır."}, {"s": "Hansı ifadədə qoşma səhv işlənib?", "o": ["mənim üçün", "evə doğru", "səhərdən bəri", "kitaba kimi"], "a": 3, "e": "«Kimi» qoşması adlıq və ya yiyəlik hallı sözlə işlənir: «kitab kimi»."}, {"s": "Hansı söz düzgün yazılıb?", "o": ["mesuliyyət", "məsuliyyət", "məsulyyət", "məsuliyət"], "a": 1, "e": "Düzgün forma: məsuliyyət."}, {"s": "Hansı cümlədə məntiqi səhv var?", "o": ["Dünən gələcəyəm.", "Dünən gəldim.", "Sabah gələcəyəm.", "İndi gəlirəm."], "a": 0, "e": "«Dünən» keçmişi bildirir, feil isə gələcək zamandadır."}]$q$::jsonb from public.items where slug='qar-sehv'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

