  on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, sort=excluded.sort, price=excluded.price, question_count=excluded.question_count, minutes=excluded.minutes, mode=excluded.mode;
insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "«Gözəlləşdirilməkdədir» sözündə neçə şəkilçi var?", "o": ["4", "5", "6", "7"], "a": 2, "e": "göz+əl+ləş+dir+il+mək+də+dir — çoxmərhələli söz quruluşudur."}, {"s": "Hansı cümlədə mübtəda söz birləşməsi ilə ifadə olunub?", "o": ["Uşaq gəldi.", "Mənim dostum gəldi.", "Gəldim.", "Soyuqdur."], "a": 1, "e": "«Mənim dostum» III növ təyini söz birləşməsidir və bütövlükdə mübtədadır."}, {"s": "«Oxuyanlar» sözündə hansı proses baş verib?", "o": ["Sifətin isimləşməsi", "Feili sifətin isimləşməsi", "Feilin sifətləşməsi", "Zərfin isimləşməsi"], "a": 1, "e": "«Oxuyan» feili sifəti cəm şəkilçisi qəbul edərək isimləşib."}, {"s": "Hansı cümlədə budaq cümlə mübtəda budaq cümləsidir?", "o": ["Kim çalışsa, o qazanar.", "Gəldim ki, görüşək.", "Yağış yağdı, çünki bulud var idi.", "Gələn getdi."], "a": 0, "e": "Budaq cümlə baş cümlənin mübtədasını («o») izah edir."}, {"s": "«Baxışlarımızda» sözündə kök hansıdır?", "o": ["baxış", "bax", "baxışlar", "baxışımız"], "a": 1, "e": "Kök «bax» feilidir; «-ış» leksik şəkilçisi ilə isim düzəlib."}, {"s": "Hansı sözdə iki leksik şəkilçi ardıcıl gəlib?", "o": ["kitablar", "dostluqda", "işçilik", "evdən"], "a": 2, "e": "iş + çi + lik — hər ikisi sözdüzəldici şəkilçidir."}, {"s": "«Nə qədər ki yaşayıram, çalışacağam» cümləsində budaq cümlənin növü nədir?", "o": ["Zaman", "Şərt", "Səbəb", "Məqsəd"], "a": 0, "e": "«Nə qədər ki» burada zaman məzmunu bildirir."}, {"s": "Hansı feil formasında həm inkar, həm zaman şəkilçisi var?", "o": ["gəlmirəm", "gəlmək", "gələn", "gəl"], "a": 0, "e": "gəl + mir (inkar + indiki zaman) + əm (şəxs)."}, {"s": "«Yüzlərlə adam» ifadəsində «yüzlərlə» hansı nitq hissəsidir?", "o": ["Müəyyən miqdar sayı", "Qeyri-müəyyən miqdar sayı", "Sıra sayı", "Zərf"], "a": 1, "e": "Cəm və «-lə» şəkilçisi qəbul edərək təqribi miqdar bildirir."}, {"s": "Hansı cümlədə xəbər mürəkkəb feillə ifadə olunub?", "o": ["Kömək etdi.", "Gəldi.", "Oxudu.", "Yazdı."], "a": 0, "e": "«Kömək etmək» ad + köməkçi feil quruluşlu mürəkkəb feildir."}, {"s": "«Sən gələndə mən gedirdim» cümləsində «gələndə» nədir?", "o": ["Feili sifət", "Feili bağlama", "Məsdər", "Xəbər"], "a": 1, "e": "«-anda, -əndə» zaman bildirən feili bağlama şəkilçisidir."}, {"s": "Hansı sözdə həm mənsubiyyət, həm hal şəkilçisi var?", "o": ["kitablar", "kitabımda", "kitabda", "kitabçı"], "a": 1, "e": "kitab + ım (mənsubiyyət) + da (yerlik hal)."}, {"s": "«Ağ-qara» sözü hansı üsulla yaranıb?", "o": ["Morfoloji", "Sintaktik (iki kökün birləşməsi)", "Fonetik", "Semantik"], "a": 1, "e": "İki müstəqil sözün defislə birləşməsindən yaranıb."}, {"s": "Hansı cümlədə zərflik səbəb bildirir?", "o": ["Tez gəldi.", "Xəstəlikdən gələ bilmədi.", "Burada oturdu.", "Sürətlə qaçdı."], "a": 1, "e": "«Xəstəlikdən» — «nə səbəbə?» sualına cavab verir."}, {"s": "«Mənim kitabım» və «kitabım» ifadələri arasındakı fərq nədir?", "o": ["Mənaca fərqlidir", "Birincidə yiyəlik hallı söz iştirak edir", "İkincisi səhvdir", "Fərq yoxdur"], "a": 1, "e": "Birincisi III növ təyini söz birləşməsidir, ikincisi tək mənsubiyyət formasıdır."}, {"s": "Hansı sözdə samit düşümü baş verir?", "o": ["kiçik — kiçildi", "kitab — kitabı", "ev — evdə", "qapı — qapıda"], "a": 0, "e": "kiçik → kiçildi: son «k» samiti düşür."}, {"s": "«Oxu!» və «Oxuyun!» formaları arasındakı fərq nədir?", "o": ["Zaman fərqi", "Şəxs və kəmiyyət fərqi", "Növ fərqi", "Fərq yoxdur"], "a": 1, "e": "Hər ikisi əmr şəklidir, lakin biri II şəxs tək, digəri II şəxs cəmdir."}, {"s": "Hansı cümlədə tamamlıq budaq cümləsi var?", "o": ["Bilirəm ki, gələcəksən.", "Kim gəlsə, qalacaq.", "Hava elə soyuq idi ki, çıxmadıq.", "Gəldim ki, görüşək."], "a": 0, "e": "Budaq cümlə «nəyi bilirəm?» sualına cavab verir."}, {"s": "«Daş-qaş» tipli sözlər necə adlanır?", "o": ["Mürəkkəb sözlər", "Qoşa sözlər", "Düzəltmə sözlər", "Sadə sözlər"], "a": 1, "e": "Qoşa sözlər defislə yazılır və ümumiləşdirici məna bildirir."}, {"s": "Hansı sözdə vurğu mənanı dəyişir?", "o": ["alma", "kitab", "qapı", "dost"], "a": 0, "e": "almá (meyvə) — álma (almamaq, əmr forması). Vurğunun yeri mənanı dəyişir."}]$q$::jsonb from public.items where slug='qar-cetin'
  on conflict (item_id) do update set lesson=excluded.lesson, questions=excluded.questions;

