insert into public.item_content (item_id,lesson,questions) select id,null,$q$[{"s": "Azərbaycan dilində neçə sait var?", "o": ["7", "8", "9", "10"], "a": 2, "e": "9 sait: a, e, ə, i, ı, o, ö, u, ü."}, {"s": "İsmin neçə halı var?", "o": ["5", "6", "7", "4"], "a": 1, "e": "6 hal."}, {"s": "Feilin neçə şəkli var?", "o": ["4", "5", "6", "7"], "a": 2, "e": "6 şəkil."}, {"s": "Sifətin neçə dərəcəsi var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Adi, azaltma, çoxaltma."}, {"s": "Əvəzliyin neçə növü var?", "o": ["4", "5", "6", "7"], "a": 2, "e": "6 növ."}, {"s": "Zərfin neçə növü var?", "o": ["3", "4", "5", "6"], "a": 2, "e": "5 növ."}, {"s": "Feilin neçə növü var?", "o": ["3", "4", "5", "6"], "a": 2, "e": "5 növ."}, {"s": "Təyini söz birləşmələrinin neçə növü var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "3 növ."}, {"s": "Azərbaycan əlifbasında neçə hərf var?", "o": ["30", "31", "32", "33"], "a": 2, "e": "32 hərf."}, {"s": "Cümlənin neçə baş üzvü var?", "o": ["1", "2", "3", "4"], "a": 1, "e": "Mübtəda və xəbər."}, {"s": "Cümlənin neçə ikinci dərəcəli üzvü var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Tamamlıq, təyin, zərflik."}, {"s": "Nitq hissələrinin neçəsi əsasdır?", "o": ["5", "6", "7", "8"], "a": 1, "e": "İsim, sifət, say, əvəzlik, feil, zərf."}, {"s": "Köməkçi nitq hissələrinin sayı neçədir?", "o": ["3", "4", "5", "6"], "a": 2, "e": "Qoşma, bağlayıcı, ədat, modal söz, nida."}, {"s": "Feilin neçə zamanı var?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Keçmiş, indiki, gələcək."}, {"s": "Quruluşuna görə sözlər neçə yerə bölünür?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Sadə, düzəltmə, mürəkkəb."}, {"s": "Mürəkkəb cümlələr neçə yerə bölünür?", "o": ["2", "3", "4", "5"], "a": 0, "e": "Tabesiz və tabeli."}, {"s": "Saylar neçə yerə bölünür?", "o": ["2", "3", "4", "5"], "a": 0, "e": "Miqdar və sıra sayları."}, {"s": "Azərbaycan dilində neçə samit var?", "o": ["21", "22", "23", "24"], "a": 2, "e": "23 samit."}, {"s": "Cümlələr məqsədinə görə neçə yerə bölünür?", "o": ["2", "3", "4", "5"], "a": 2, "e": "Nəqli, sual, əmr, nida."}, {"s": "Təsriflənməyən feil formalarının sayı neçədir?", "o": ["2", "3", "4", "5"], "a": 1, "e": "Məsdər, feili sifət, feili bağlama."}]$q$::jsonb from public.items where slug='qar-suret'
